const definitions: Record<string, Omit<ConversationMvpClaim, 'slug' | 'provenance'>> = {
  'paro-juvenil-baja': { prompt: 'El paro juvenil ha bajado casi a la mitad desde 2015', aliases: ['ha bajado el paro juvenil', 'el desempleo juvenil se ha reducido', 'hay menos paro entre los jóvenes', 'el paro juvenil cayó desde 2015', 'España ha reducido el paro juvenil'], propositions: ['La tasa de paro de las personas de 15 a 24 años bajó del 48,3% en 2015 al 24,9% en 2025.', 'La reducción demuestra que el paro juvenil ha desaparecido.', 'La tasa incluye a toda la juventud, también a quienes estudian y no buscan trabajo.'], concern: 'El paro juvenil se redujo con claridad, pero sigue siendo alto y la tasa solo se calcula sobre jóvenes que participan en el mercado laboral.', supports: 'Eurostat registra una bajada del 48,3% en 2015 al 24,9% en 2025, con un repunte al 38,3% en 2020.', limit: 'El denominador es la población activa de 15 a 24 años. No incluye a quienes estudian y no buscan trabajo, ni mide por sí solo salarios, duración, emancipación o calidad del empleo.', question: '¿Quieres comparar la tasa, el número absoluto de jóvenes sin trabajo o la calidad y estabilidad del empleo?', reply: 'Sí: el paro juvenil bajó casi a la mitad, del 48,3% en 2015 al 24,9% en 2025. Pero sigue siendo alto y la tasa solo incluye a jóvenes activos; no describe a toda la juventud ni demuestra que el empleo sea estable.', visualLabel: 'Una tasa más baja no significa que el problema haya desaparecido', visuals: { key: { value: '-23,4 p.p.', label: 'Cambio del paro de 15–24 años', period: '2015 → 2025' }, trend: { available: true, labels: ['2015','2017','2019','2020','2021','2023','2025'], values: [48.3,38.6,32.5,38.3,35,28.7,24.9], label: 'Tasa de paro de 15 a 24 años', unit: '% de la población activa' }, caveat: 'La serie bajó, pero el denominador excluye a quienes no trabajan ni buscan trabajo y el indicador no mide por sí solo la calidad del empleo.' } },
  'paro-juvenil-espana-ue': { prompt: 'España tiene más paro juvenil que la Unión Europea', aliases: ['España tiene más desempleo juvenil que Europa', 'el paro juvenil español supera al europeo', 'España tiene una tasa de paro juvenil mayor que la Unión Europea', 'paro juvenil frente a Europa', 'comparación europea del paro juvenil'], propositions: ['En 2025, la tasa de paro de la población activa de 15 a 24 años fue del 24,9% en España y del 15,2% en la Unión Europea.', 'La diferencia confirma una brecha en ese indicador.', 'La comparación demuestra por sí sola las causas de la diferencia o la calidad del empleo juvenil.'], concern: 'España registra más paro juvenil que la Unión Europea en la misma medida comparable, aunque esa diferencia no explica por sí sola sus causas.', supports: 'Eurostat registra un 24,9% en España y un 15,2% en la Unión Europea en 2025: 9,7 puntos porcentuales de diferencia.', limit: 'El denominador es la población activa de 15 a 24 años. No incluye a quienes estudian y no buscan trabajo, ni mide por sí solo salarios, duración, estabilidad o calidad del empleo.', question: '¿Quieres comparar la tasa, el número de jóvenes sin trabajo o las causas de la diferencia?', reply: 'Sí: en 2025 España tenía una tasa de paro juvenil del 24,9%, frente al 15,2% de la Unión Europea. Son 9,7 puntos más, pero el indicador se calcula sobre jóvenes activos y no explica por sí solo las causas.', visualLabel: 'Una brecha comparable no es una explicación causal', visuals: { key: { value: '+9,7 p.p.', label: 'España frente a la Unión Europea', period: '2025' }, trend: { available: false, labels: [], values: [], label: 'Evolución del paro juvenil', unit: '% de la población activa' }, comparison: { labels: ['España', 'Unión Europea'], values: [24.9, 15.2], label: 'Tasa de paro juvenil', unit: '% de la población activa de 15 a 24 años' }, caveat: 'La comparación usa jóvenes activos de 15 a 24 años. No mide por sí sola causas, salarios, duración, estabilidad o calidad del empleo.' } },
  'abandono-escolar-espana-ue': { prompt: 'España tiene más abandono escolar temprano que la Unión Europea', aliases: ['España tiene más abandono escolar que Europa', 'el abandono educativo español supera al europeo', 'España abandona más los estudios que la UE', 'abandono escolar frente a Europa', 'comparación europea del abandono escolar'], propositions: ['En 2025, el 12,8% de las personas de 18 a 24 años abandonó pronto la educación y la formación en España, frente al 9,1% en la Unión Europea.', 'La diferencia confirma una brecha en ese indicador.', 'La comparación demuestra por sí sola las causas de la diferencia o la calidad completa del sistema educativo.'], concern: 'España registra más abandono escolar temprano que la Unión Europea en la misma medida comparable, aunque esa diferencia no explica por sí sola sus causas.', supports: 'Eurostat registra un 12,8% en España y un 9,1% en la Unión Europea en 2025: 3,7 puntos porcentuales de diferencia.', limit: 'El indicador se calcula sobre personas de 18 a 24 años. No es la tasa de paro juvenil ni mide por sí solo el rendimiento escolar completo, la calidad educativa o la trayectoria de cada joven.', question: '¿Quieres comparar la tasa, las diferencias territoriales o las causas del abandono?', reply: 'Sí: en 2025 España registró un 12,8% de abandono escolar temprano entre las personas de 18 a 24 años, frente al 9,1% de la Unión Europea. Son 3,7 puntos más, pero el indicador no explica por sí solo las causas ni mide toda la calidad educativa.', visualLabel: 'Una brecha comparable no es una explicación causal', visuals: { key: { value: '+3,7 p.p.', label: 'España frente a la Unión Europea', period: '2025' }, trend: { available: false, labels: [], values: [], label: 'Evolución del abandono escolar temprano', unit: '% de personas de 18 a 24 años' }, comparison: { labels: ['España', 'Unión Europea'], values: [12.8, 9.1], label: 'Abandono escolar temprano', unit: '% de personas de 18 a 24 años' }, caveat: 'La comparación usa la proporción de personas de 18 a 24 años que abandonaron pronto la educación y la formación. No es paro juvenil ni una medida completa de calidad educativa.' } },
  'sobrecarga-vivienda-2025': { prompt: 'El 7,2% de la población soporta una sobrecarga del coste de la vivienda en España', aliases: ['qué porcentaje soporta sobrecarga de vivienda','porcentaje de personas con sobrecarga de vivienda','cuántas personas pagan más del 40% por la vivienda','porcentaje personas soporta sobrecarga coste vivienda','sobrecarga vivienda 2025'], propositions: ['El 7,2% de la población de referencia estaba en hogares con sobrecarga en 2025.','Sobrecarga significa que cada hogar paga más del 40% de su renta por la vivienda.','El porcentaje nacional describe igual a todos los barrios y rentas.'], concern: 'El 7,2% es una medida concreta con un umbral definido, pero no resume todas las formas de dificultad para acceder o mantener una vivienda.', supports: 'Eurostat registra un 7,2% en 2025 para la población de referencia de la serie.', limit: 'Sobrecarga significa costes totales superiores al 40% de la renta disponible equivalente; no mide por sí sola calidad, renuncia a vivienda, territorio ni cada contrato.', question: '¿Quieres medir sobrecarga, acceso a una vivienda o esfuerzo en una renta y territorio concretos?', reply: 'En 2025, el 7,2% de la población de referencia vivía en hogares cuyos costes de vivienda superaban el 40% de la renta disponible equivalente. Es una media nacional y no resume toda la dificultad de acceso.', visualLabel: 'Un umbral estadístico no resume toda la asequibilidad', visuals: { key: { value: '7,2 %', label: 'Población en hogares con sobrecarga', period: '2025' }, trend: { available: true, labels: ['2015','2017','2019','2021','2023','2025'], values: [10.3,9.8,8.5,9.9,8.2,7.2], label: 'Sobrecarga del coste de la vivienda', unit: '% de la población' }, caveat: 'Eurostat usa un umbral del 40% de la renta disponible equivalente. No mide por sí solo calidad, acceso, territorio o renuncia a una vivienda adecuada.' } },
  'espana-no-tiene-100-millones': { prompt: 'España tiene 100 millones de habitantes', aliases: ['España ya tiene cien millones de personas','hay 100 millones de habitantes en España','España llegará a 100 millones de habitantes','España 100 millones habitantes'], propositions: ['España tiene aproximadamente 49,13 millones de residentes en 2025.','España tiene 100 millones de residentes.','Una predicción futura puede comprobarse sin indicar fecha ni hipótesis.'], concern: 'La cifra de 100 millones no coincide con la población residente observada; si se trata de una predicción, hay que fijar un año y un modelo.', supports: 'Eurostat registra 49.128.297 residentes en España en 2025.', limit: 'La población residente es un stock en una fecha. No equivale a llegadas, población flotante ni una previsión futura.', question: '¿La frase describe la población actual o predice cuándo se alcanzarán 100 millones?', reply: 'No: Eurostat registra 49,13 millones de residentes en España en 2025, no 100 millones. Si es una predicción, hace falta indicar para qué año y con qué hipótesis.', visualLabel: 'La cifra observada y una predicción futura no son lo mismo', visuals: { key: { value: '49,13 M', label: 'Residentes registrados', period: '2025' }, trend: { available: true, labels: ['2015','2017','2019','2021','2023','2025'], values: [46.43,46.65,46.92,47.4,48.09,49.13], label: 'Población residente de España', unit: 'millones de personas' }, caveat: 'El stock observado no es una predicción y no equivale a llegadas migratorias ni a población flotante.' } },
  'precios-vivienda-causan-crisis': { prompt: 'La subida del precio de la vivienda demuestra qué causa la crisis en España', aliases: ['los precios de la vivienda causan la crisis','el precio de la vivienda explica la crisis','precios vivienda causan crisis España','la subida de la vivienda demuestra la causa de la crisis','la vivienda cara es la causa de la crisis'], propositions: ['El precio nacional de la vivienda libre ha subido.','La subida de precios demuestra por sí sola qué causa la crisis.','El efecto de cada causa es igual en todos los mercados.'], concern: 'La vivienda cara empeora el acceso, pero el precio observado es el resultado que hay que explicar, no una causa única demostrada.', supports: 'El índice nacional registró una subida interanual del 12,9% en el primer trimestre de 2026.', limit: 'La serie de precios no separa por sí sola la oferta, la demanda, los hogares, el crédito, el alquiler turístico o las políticas; la causalidad necesita territorio, periodo y mecanismo.', question: '¿Quieres comprobar la causa en España, en una comunidad o en un municipio concreto?', reply: 'Los precios sí han subido y eso empeora el acceso, pero la subida es el resultado que hay que explicar, no una prueba de una sola causa. Hay que comparar oferta, hogares, crédito, alquiler turístico y políticas en cada mercado.', visualLabel: 'Un resultado de mercado no demuestra una causa única', visuals: { key: { value: '+12,9 %', label: 'Subida interanual de vivienda libre', period: '1T 2026' }, trend: { available: true, labels: ['T2 24','T4 24','T2 25','T4 25','T1 26'], values: [7.8,11.3,12.7,12.9,12.9], label: 'Precio de vivienda libre y causalidad', unit: '% interanual' }, regionTopic: 'vivienda', caveat: 'La subida observada no distingue qué mecanismo explica el cambio ni permite atribuir toda la crisis a una sola causa.' } },
  'precio-vivienda-ha-subido': { prompt: 'Los precios de la vivienda han subido en España', aliases: ['los precios de la vivienda suben','la vivienda ha subido de precio','el precio de los pisos ha aumentado','la vivienda es más cara que antes','precios vivienda España'], propositions: ['La serie nacional del INE muestra una subida interanual del precio de la vivienda libre.','La misma subida se aplica a cada vivienda, barrio y comunidad.','El índice de compraventas equivale al precio del alquiler.'], concern: 'La vivienda libre ha subido de precio en la media nacional, pero el promedio no cuenta la misma historia para cada barrio, vivienda o contrato.', supports: 'El INE registra una subida interanual del 7,8% en el segundo trimestre de 2024 al 12,9% en el primer trimestre de 2026.', limit: 'El índice mide vivienda libre efectivamente comprada. No es el precio de anuncio, el alquiler ni la experiencia de cada hogar.', question: '¿Quieres comparar la media nacional, una comunidad, un barrio o el precio del alquiler?', reply: 'Sí: el INE registró una subida interanual del precio de la vivienda libre, del 7,8% en el segundo trimestre de 2024 al 12,9% en el primer trimestre de 2026. Es una media nacional y no describe cada vivienda o alquiler.', visualLabel: 'La subida media no es el precio de cada vivienda', visuals: { key: { value: '+12,9 %', label: 'Subida interanual de vivienda libre', period: '1T 2026' }, trend: { available: true, labels: ['T2 24','T4 24','T2 25','T4 25','T1 26'], values: [7.8,11.3,12.7,12.9,12.9], label: 'Variación anual del precio de vivienda libre', unit: '% interanual' }, regionTopic: 'vivienda', caveat: 'La serie nacional no describe el precio de cada vivienda, barrio, comunidad, anuncio o alquiler.' } },
  'poblacion-residente-supera-49m': { prompt: 'España supera los 49 millones de residentes', aliases: ['España ya tiene más de 49 millones de habitantes','la población de España supera los 49 millones','hay 49 millones de personas en España'], propositions: ['España tenía 49.128.297 residentes en 2025.','La cifra equivale al número de llegadas migratorias de ese año.','El aumento nacional describe igual cada municipio y cada grupo.'], concern: 'La población residente española ha superado los 49 millones, pero un total nacional no cuenta por sí solo sus componentes ni la experiencia de cada territorio.', supports: 'Eurostat registra 49.128.297 residentes en España en 2025.', limit: 'Es un stock de población residente en una fecha anual. No es un flujo de llegadas y no explica por sí solo nacimientos, defunciones, migración o diferencias locales.', question: '¿Quieres separar población residente, llegadas, nacimientos, migración o evolución de un territorio?', reply: 'Sí: España superó los 49 millones de residentes en 2025. Es una cifra de población acumulada, no el número de llegadas de ese año ni una explicación automática del cambio.', visualLabel: 'Población residente y llegadas son medidas distintas', visuals: { key: { value: '49,13 M', label: 'Población residente', period: '2025' }, trend: { available: true, labels: ['2015','2017','2019','2021','2023','2025'], values: [46.43,46.65,46.92,47.4,48.09,49.13], label: 'Población residente de España', unit: 'millones de personas' }, caveat: 'Un stock de residentes no equivale a las llegadas de un año ni identifica por sí solo qué componente explica el cambio.' } },
  'poblacion-nacida-fuera-sube': { prompt: 'La población nacida fuera de España ha aumentado desde 2015', aliases: ['hay más personas nacidas fuera de España','ha aumentado la población inmigrante','España tiene más residentes nacidos en el extranjero','cada vez hay más gente nacida fuera'], propositions: ['La categoría «Foreign country» pasó de 5.883.891 residentes en 2015 a 9.464.210 en 2025.','País de nacimiento y nacionalidad son la misma medida.','El aumento nacional explica por sí solo sus efectos en empleo, ayudas, seguridad o integración.'], concern: 'La población residente nacida en un país extranjero ha crecido de forma clara, pero el dato necesita conservar la distinción entre país de nacimiento, nacionalidad, flujos y efectos.', supports: 'Eurostat registra 5.883.891 residentes en la categoría «Foreign country» en 2015 y 9.464.210 en 2025.', limit: 'Es un stock anual por país de nacimiento. No equivale a nacionalidad, llegadas irregulares, situación administrativa ni una explicación causal de sus efectos.', question: '¿Quieres comparar país de nacimiento, nacionalidad, llegadas o la distribución por territorio?', reply: 'Sí: la población residente nacida en un país extranjero aumentó de 5,88 millones en 2015 a 9,46 millones en 2025 según Eurostat. Es un stock por país de nacimiento, no el número de llegadas ni una explicación automática de sus efectos.', visualLabel: 'Más residentes nacidos fuera no equivale a una sola historia', visuals: { key: { value: '9,46 M', label: 'Residentes nacidos en un país extranjero', period: '2025' }, trend: { available: true, labels: ['2015','2017','2019','2021','2023','2025'], values: [5.884,6.015,6.549,7.255,8.204,9.464], label: 'Residentes por país de nacimiento', unit: 'millones de personas' }, caveat: 'País de nacimiento, nacionalidad, llegadas y situación administrativa son medidas distintas; este dato no prueba efectos causales.' } },
  'ipc-junio-2026-positivo': { prompt: 'Los precios de consumo subieron un 3,2% interanual en junio de 2026', aliases: ['el IPC de junio fue del 3,2%','la inflación anual fue del 3,2% en junio','los precios subieron un 3,2% en junio','IPC 3,2 junio 2026'], propositions: ['El IPC general registró una tasa anual del 3,2% en junio de 2026.','Todos los productos y hogares afrontaron exactamente una subida del 3,2%.','Una tasa positiva demuestra por sí sola que todos los hogares perdieron poder adquisitivo.'], concern: 'Los precios medios de consumo siguieron aumentando, pero la media nacional no cuenta exactamente la experiencia de cada hogar.', supports: 'El INE registró un IPC anual del 3,2% en junio de 2026, igual que en mayo.', limit: 'El IPC es una media nacional. No equivale a la factura de cada hogar ni determina por sí solo el poder adquisitivo, que también depende de renta y composición del gasto.', question: '¿Quieres comparar la tasa general, un producto concreto o el poder adquisitivo de un hogar?', reply: 'Sí: el IPC general subió un 3,2% interanual en junio de 2026 según el INE. Es una media nacional; no significa que cada producto o familia pagara exactamente un 3,2% más.', visualLabel: 'La media del IPC no es la factura de cada hogar', visuals: { key: { value: '3,2 %', label: 'IPC general · tasa anual', period: 'Junio 2026' }, trend: { available: true, labels: ['Jun. 2025','Dic. 2025','Mar. 2026','Jun. 2026'], values: [2.3,2.9,3.4,3.2], label: 'Tasa anual del IPC general', unit: '% interanual' }, caveat: 'La tasa media nacional no describe cada producto, contrato, territorio o cesta familiar.' } },
  'tasa-empleo-sube': { prompt: 'La tasa de empleo de 20 a 64 años ha subido desde 2015', aliases: ['ha subido la tasa de empleo','hay más empleo entre 20 y 64 años','la tasa de ocupación ha aumentado','España tiene más empleo que en 2015'], propositions: ['La tasa de empleo de 20 a 64 años pasó del 62,0% al 72,4% entre 2015 y 2025.','La subida demuestra que todos los empleos son estables y suficientes.','La tasa nacional describe igual la situación de cada persona.'], concern: 'La proporción de personas ocupadas de 20 a 64 años ha mejorado, pero la cifra no responde por sí sola a la calidad, salario o seguridad económica del empleo.', supports: 'Eurostat registra una subida del 62,0% en 2015 al 72,4% en 2025.', limit: 'El indicador mide empleo sobre la población de 20 a 64 años. No es la tasa de paro ni mide por sí solo salario, horas, estabilidad, territorio o sector.', question: '¿Quieres comparar la tasa de empleo, el paro o la calidad del trabajo por edad y territorio?', reply: 'Sí: la tasa de empleo de 20 a 64 años subió del 62,0% al 72,4% entre 2015 y 2025. Eso confirma más empleo en esa población, pero no demuestra que todo el empleo sea estable o suficiente.', visualLabel: 'Más empleo no equivale automáticamente a mejor empleo', visuals: { key: { value: '+10,4 p.p.', label: 'Cambio de la tasa de empleo', period: '2015 → 2025' }, trend: { available: true, labels: ['2015','2017','2019','2020','2021','2023','2025'], values: [62,65.5,68,65.7,67.5,70.5,72.4], label: 'Tasa de empleo de 20 a 64 años', unit: '% de la población' }, caveat: 'La tasa de empleo no mide por sí sola salario, horas, estabilidad, calidad ni suficiencia económica.' } },
  'inmigracion-delincuencia': { prompt: 'Los inmigrantes crean inseguridad', aliases: ['inmigracion','inmigrantes','extranjeros','delincuencia','crimen','inseguridad','peligro','delinquen'], propositions: ['Hay diferencias en algunas tasas de condena por nacionalidad.','La inmigración ha causado un aumento general de la delincuencia.','La nacionalidad explica por sí sola quién delinque.'], concern: 'Puede existir una experiencia real de inseguridad o de cambios en un barrio, pero eso no identifica automáticamente su causa.', supports: 'En 2024 las tasas brutas de condena fueron distintas entre personas de nacionalidad extranjera y española.', limit: 'La comparación no demuestra causalidad: edad, sexo, renta, territorio, situación legal y exposición policial también son diferentes. Además, la mayoría absoluta de condenados tenía nacionalidad española.', question: '¿Hablamos de delincuencia nacional, de un delito concreto o de un barrio determinado?', reply: 'Puede haber una diferencia estadística, pero no demuestra que la inmigración sea la causa general de la inseguridad. Conviene separar el delito concreto, el lugar y los factores demográficos.', visualLabel: 'Diferencia estadística no equivale a causalidad', visuals: { key: { value: '15,7 vs 6,2', label: 'Condenas por cada 1.000 adultos', period: '2024' }, trend: { available: false, labels: [], values: [], label: 'Serie temporal de delincuencia e inmigración', unit: 'No hay una serie comparable conectada' }, comparison: { labels: ['Nacionalidad extranjera','Nacionalidad española'], values: [15.7,6.2], label: 'Adultos condenados por 1.000', unit: 'por 1.000 adultos' }, regionTopic: 'seguridad', caveat: 'Las tasas brutas no ajustan por edad, sexo, renta, territorio ni exposición policial. La serie autonómica disponible registra recuentos de criminalidad, no una tasa comparable para probar esta causa.' } },
  'alquileres-suben': { prompt: 'Los alquileres han subido en España desde 2015', aliases: ['el alquiler ha subido','los alquileres han subido','el precio del alquiler sube','los alquileres son más caros','los alquileres son más caros que en 2015','el alquiler no ha subido','el alquiler está igual que en 2015'], propositions: ['El índice armonizado de alquileres efectivos aumentó entre 2015 y 2025.','La misma subida se aplica a cada contrato y municipio.'], concern: 'El encarecimiento medio del alquiler es una señal útil, pero la experiencia depende del contrato, el municipio y el tipo de vivienda.', supports: 'Eurostat registra un aumento aproximado del 14,6% entre enero de 2015 y diciembre de 2025 en la serie armonizada de alquileres efectivos, con base 2015=100.', limit: 'La media nacional no equivale al precio de anuncio de cada piso ni permite inferir la subida de un contrato o municipio concreto.', question: '¿Quieres comparar la media nacional, una ciudad concreta o el precio de un contrato nuevo?', reply: 'Sí: el índice de Eurostat muestra que los alquileres efectivos eran aproximadamente un 14,6% más caros en diciembre de 2025 que en enero de 2015. Es una media nacional y no describe cada contrato.', visualLabel: 'El promedio nacional no es el precio de cada contrato', visuals: { key: { value: '+14,6 %', label: 'Índice de alquileres efectivos', period: 'Ene. 2015 → dic. 2025' }, trend: { available: true, labels: ['2015','2020','2025'], values: [100.2,104.66,114.78], label: 'Evolución del índice de alquileres efectivos', unit: 'índice · 2015=100' }, regionTopic: 'vivienda', caveat: 'La serie armonizada mide alquileres efectivos a escala nacional. No es el precio de anuncio y oculta diferencias entre contratos, viviendas y municipios.' } },
  'espana-pierde-poblacion': { prompt: 'España está perdiendo población', aliases: ['España pierde población','la población de España está bajando','la población está bajando','cada vez hay menos gente en España','España se está despoblando'], propositions: ['Algunos territorios españoles sí pierden población.','La población total de España está disminuyendo.','Una tasa nacional positiva significa que todos los municipios crecen.'], concern: 'La despoblación de algunos municipios es una experiencia real, pero no equivale a que el conjunto del país esté perdiendo población.', supports: 'Eurostat registra una tasa de cambio total positiva de 9,4 por cada 1.000 habitantes en España en 2025.', limit: 'La tasa nacional combina los componentes del cambio demográfico y oculta diferencias territoriales; no separa por sí sola nacimientos, defunciones y migración.', question: '¿Quieres comprobar España en conjunto o un municipio concreto, y separar saldo natural de migración?', reply: 'España no estaba perdiendo población en la última observación nacional comparable: la tasa de cambio total fue de +9,4 por cada 1.000 habitantes en 2025. Sí hay territorios que pierden población, así que conviene decir de qué lugar hablamos.', visualLabel: 'El país y sus municipios pueden moverse en direcciones distintas', visuals: { key: { value: '+9,4', label: 'Tasa de cambio total de la población', period: '2025 · por 1.000 habitantes' }, trend: { available: true, labels: ['2015','2017','2019','2021','2023','2025'], values: [-0.1,3.2,8.5,1.8,11.1,9.4], label: 'Cambio total de la población en España', unit: 'por cada 1.000 habitantes' }, caveat: 'La tasa nacional no significa que cada municipio crezca ni identifica por sí sola cuánto corresponde a saldo natural o migración.' } },
  'espana-envejece': { prompt: 'España está cada vez más envejecida', aliases: ['España envejece','hay cada vez más personas mayores','España tiene cada vez más mayores','la población española está envejecida','cada vez hay más jubilados'], propositions: ['La proporción de personas de 65 años o más ha aumentado en España.','El envejecimiento nacional avanza igual en todos los territorios.','La evolución demográfica decide por sí sola la política de jubilación y cuidados.'], concern: 'El aumento de la población mayor es un cambio demográfico real, pero no convierte una decisión sobre pensiones o cuidados en una conclusión automática.', supports: 'La población de 65 años o más pasó del 18,4% en 2015 al 20,7% en 2025 según Eurostat.', limit: 'La proporción nacional no describe cada comunidad, municipio o generación y no decide por sí sola cómo repartir los costes de pensiones, cuidados y sanidad.', question: '¿Quieres medir el envejecimiento por proporción de mayores, dependencia demográfica o territorio?', reply: 'Sí: España está más envejecida que hace una década. La población de 65 años o más pasó del 18,4% al 20,7% entre 2015 y 2025. Eso describe un cambio demográfico, no una política concreta.', visualLabel: 'Más población mayor no decide por sí sola la política', visuals: { key: { value: '20,7 %', label: 'Población de 65 años o más', period: '2025' }, trend: { available: true, labels: ['2015','2017','2019','2021','2023','2025'], values: [18.4,18.9,19.3,19.6,20.1,20.7], label: 'Proporción de población de 65 años o más', unit: '% de la población' }, caveat: 'La media nacional oculta diferencias territoriales y no determina por sí sola la edad de jubilación, el gasto sanitario o la política de cuidados.' } },
  'espana-fecundidad-baja': { prompt: 'España tiene menos de 1,2 hijos por mujer', aliases: ['España tiene una fecundidad muy baja','la natalidad está por los suelos','cada mujer tiene menos de 1,2 hijos','en España nacen muy pocos niños','España no tiene hijos'], propositions: ['La tasa global de fecundidad española fue inferior a 1,2 hijos por mujer en 2024.','Todas las mujeres tienen el mismo número de hijos.','La cifra por sí sola explica por qué nacen menos niños.'], concern: 'La fecundidad media es muy baja y ha descendido, pero la cifra no convierte una experiencia demográfica en una explicación única de las decisiones familiares.', supports: 'Eurostat registra 1,10 hijos por mujer en España en 2024, frente a 1,33 en 2015.', limit: 'La media nacional no describe a cada mujer ni separa vivienda, empleo, renta, cuidados, edad y proyectos familiares.', question: '¿Quieres medir la media nacional, el número de nacimientos o las causas de la fecundidad?', reply: 'Sí: España registró 1,10 hijos por mujer en 2024, por debajo de 1,2. Es una media demográfica y no demuestra por sí sola qué causa las decisiones familiares.', visualLabel: 'Una media nacional no describe cada familia', visuals: { key: { value: '1,10', label: 'Hijos por mujer', period: '2024' }, trend: { available: true, labels: ['2015','2017','2019','2021','2023','2024'], values: [1.33,1.31,1.23,1.18,1.12,1.10], label: 'Tasa global de fecundidad en España', unit: 'hijos por mujer' }, caveat: 'La media no identifica la experiencia de cada mujer ni separa vivienda, empleo, renta, cuidados, edad y proyectos familiares.' } },
  'espana-menores-disminuyen': { prompt: 'En España hay cada vez menos menores de 15 años', aliases: ['cada vez hay menos niños en España','España tiene menos niños','hay menos menores','la población infantil está bajando','España se está quedando sin niños'], propositions: ['La proporción de menores de 15 años disminuyó en España entre 2015 y 2025.','El número absoluto de menores disminuyó exactamente en la misma proporción.','El cambio demográfico tiene una sola causa.'], concern: 'La población infantil representa una parte menor del conjunto de residentes, pero eso no equivale automáticamente a contar menos menores en términos absolutos.', supports: 'Eurostat registra un descenso de la proporción de menores de 15 años: del 15,1% en 2015 al 12,9% en 2025.', limit: 'La serie mide una proporción y no separa nacimientos, migración, estructura de edades ni el número absoluto de menores.', question: '¿Quieres comparar la proporción de menores, el número absoluto o las causas del cambio?', reply: 'Sí: los menores de 15 años representaban el 12,9% de la población en 2025, frente al 15,1% en 2015. Es una proporción y no demuestra por sí sola cuál es la causa.', visualLabel: 'Una proporción menor no es automáticamente un recuento menor', visuals: { key: { value: '12,9 %', label: 'Población menor de 15 años', period: '2025' }, trend: { available: true, labels: ['2015','2017','2019','2021','2023','2025'], values: [15.1,15.0,14.7,14.2,13.6,12.9], label: 'Proporción de población menor de 15 años', unit: '% de la población' }, caveat: 'La serie mide la proporción sobre el total residente. No identifica por sí sola el número absoluto de menores ni separa nacimientos y migración.' } },
  'renta-mediana-sube': { prompt: 'La renta mediana disponible ha subido en España desde 2015', aliases: ['la renta mediana ha subido','los ingresos medianos han aumentado','las rentas de los hogares han crecido','la renta disponible es mayor que en 2015','la renta de los hogares ha subido'], propositions: ['La renta mediana disponible equivalente aumentó entre 2015 y 2025.','La subida nominal significa que todos los hogares pueden comprar más.','La renta mediana equivale al salario de cada hogar.'], concern: 'La renta mediana es una señal útil sobre el centro de la distribución, pero no cuenta la misma historia para todos los hogares.', supports: 'Eurostat registra una subida de 13.352 € por persona en 2015 a 20.367 € en 2025.', limit: 'La serie está en euros corrientes: no descuenta inflación y no equivale al salario, patrimonio o factura de cada hogar.', question: '¿Quieres comparar renta nominal, poder adquisitivo o la situación de un hogar concreto?', reply: 'Sí, la renta mediana disponible subió de 13.352 € por persona en 2015 a 20.367 € en 2025. Son euros corrientes: para valorar el poder adquisitivo hay que descontar la inflación.', visualLabel: 'Más euros nominales no significan automáticamente más poder de compra', visuals: { key: { value: '20.367 €', label: 'Renta mediana disponible equivalente', period: '2025' }, trend: { available: true, labels: ['2015','2017','2019','2021','2023','2025'], values: [13352,14203,15015,15892,18316,20367], label: 'Renta mediana disponible equivalente', unit: '€ por persona · euros corrientes' }, caveat: 'La serie no está ajustada por inflación y la mediana no describe el cambio de cada hogar.' } },
  'esperanza-vida-alta': { prompt: 'España supera los 84 años de esperanza de vida', aliases: ['España tiene más de 84 años de esperanza de vida','la esperanza de vida en España supera los 84 años','vivimos más de 84 años','España tiene una esperanza de vida muy alta','la longevidad en España supera los 84 años'], propositions: ['La esperanza de vida al nacer en España alcanzó 84,0 años en 2024.','Todas las personas vivirán 84 años.','Una esperanza de vida alta demuestra que el acceso y la calidad sanitaria son iguales para todos.'], concern: 'España tiene una esperanza de vida alta, pero la media nacional no cuenta la misma historia para todos los territorios, grupos o estados de salud.', supports: 'Eurostat registra 84,0 años en 2024, frente a 82,7 en 2015.', limit: 'Es una media poblacional y no predice la vida exacta de cada persona ni mide por sí sola acceso sanitario, calidad o años vividos con buena salud.', question: '¿Quieres comparar esperanza de vida, años con buena salud o diferencias por territorio y grupo?', reply: 'Sí: la esperanza de vida al nacer llegó a 84,0 años en España en 2024. Es una media poblacional, no los años que vivirá cada persona ni una prueba de acceso igualitario a la sanidad.', visualLabel: 'Una media nacional no describe la salud de cada persona', visuals: { key: { value: '84,0 años', label: 'Esperanza de vida al nacer', period: '2024' }, trend: { available: true, labels: ['2015','2017','2019','2020','2021','2022','2023','2024'], values: [82.7,83.0,83.5,82.3,83.0,83.1,83.8,84.0], label: 'Esperanza de vida al nacer', unit: 'años' }, caveat: 'La medida es una media poblacional. No dice cuántos años vivirá cada persona ni cuántos se vivirán con buena salud.' } },
  'electricidad-hogares-sube': { prompt: 'El precio medio de la electricidad para hogares supera 0,28 €/kWh', aliases: ['la luz cuesta más de 28 céntimos','el precio de la electricidad supera 0,28 euros','la electricidad para hogares es cara','el precio de la luz en España supera 0,28','precio luz hogares España'], propositions: ['El precio medio de la electricidad para hogares en España superó 0,28 €/kWh en 2025-S2.','Todas las familias pagan una factura de 0,2872 €/kWh.','España es el país europeo con la electricidad más cara.'], concern: 'La serie muestra un precio doméstico unitario elevado, pero la factura real cambia según consumo, tarifa y potencia contratada.', supports: 'Eurostat registra 0,2872 €/kWh en 2025-S2, con impuestos incluidos.', limit: 'El precio por kWh no es la factura de cada hogar y no basta para establecer una posición europea sin una comparación homogénea.', question: '¿Quieres comparar el precio por kWh, la factura de un hogar o España con otros países?', reply: 'La serie de Eurostat sitúa el precio doméstico medio en 0,2872 €/kWh en 2025-S2, con impuestos incluidos. No es la factura de cada hogar: depende del consumo, la tarifa y la potencia.', visualLabel: 'El precio por kWh no es la factura mensual', visuals: { key: { value: '0,2872 €', label: 'Precio doméstico medio por kWh', period: '2025-S2' }, trend: { available: true, labels: ['2023-S1','2023-S2','2024-S1','2024-S2','2025-S1','2025-S2'], values: [0.2647,0.2552,0.2688,0.2643,0.2841,0.2872], label: 'Precio de la electricidad para hogares', unit: '€ por kWh · impuestos incluidos' }, caveat: 'El precio unitario no equivale a la factura de cada hogar: consumo, tarifa, potencia e impuestos aplicables cambian el importe.' } },
  'paro-juvenil-alto': { prompt: 'Casi uno de cada cuatro jóvenes activos está en paro', aliases: ['el paro juvenil sigue por encima del 20%','uno de cada cuatro jóvenes está en paro','los jóvenes tienen mucho paro','el desempleo juvenil en España es del 25%','paro entre los jóvenes'], propositions: ['La tasa de paro de las personas de 15 a 24 años fue 24,9% en 2025.','Una de cada cuatro personas jóvenes, incluyendo quienes no buscan trabajo, está en paro.','El dato informa por sí solo sobre la calidad del empleo juvenil.'], concern: 'El paro juvenil sigue siendo alto, aunque la tasa ha bajado y solo se calcula sobre jóvenes que participan en el mercado laboral.', supports: 'Eurostat registra 24,9% en 2025, frente a 48,3% en 2015.', limit: 'El denominador es la población activa de 15 a 24 años. No incluye a quienes estudian y no buscan trabajo, ni mide por sí solo salarios, duración o calidad del empleo.', question: '¿Quieres comparar la tasa, el número de jóvenes sin trabajo o la calidad del empleo?', reply: 'Sí: en 2025 estaba en paro el 24,9% de la población activa de 15 a 24 años en España, casi una de cada cuatro. No es el porcentaje de toda la juventud: quienes no buscan trabajo no entran en el denominador.', visualLabel: 'La tasa de paro juvenil usa la población activa como denominador', visuals: { key: { value: '24,9 %', label: 'Paro de 15–24 años', period: '2025' }, trend: { available: true, labels: ['2015','2017','2019','2020','2021','2023','2025'], values: [48.3,38.6,32.5,38.3,35,28.7,24.9], label: 'Tasa de paro de 15 a 24 años', unit: '% de la población activa' }, caveat: 'No es el porcentaje de toda la juventud. El denominador excluye a quienes no trabajan ni buscan trabajo.' } },
  'ingresos-publicos-superan-40': { prompt: 'Los ingresos públicos de España superan el 40% del PIB', aliases: ['España recauda más del 40% del PIB','los ingresos públicos superan el 40 por ciento','la recaudación pública supera el 40%','el Estado ingresa más del 40% del PIB','ingresos públicos España'], propositions: ['Los ingresos totales de las administraciones públicas equivalieron al 42,9% del PIB en 2025.','Cada hogar paga el 42,9% de su renta al Estado.','El dato identifica cuánto paga cada contribuyente.'], concern: 'Los ingresos públicos son un agregado nacional útil para comparar el tamaño de los recursos públicos, pero no son la factura fiscal de una familia.', supports: 'Eurostat registra ingresos públicos equivalentes al 42,9% del PIB en 2025, frente al 38,4% en 2015.', limit: 'La serie suma ingresos de las administraciones públicas y no separa por sí sola impuestos, cotizaciones, hogares, rentas ni servicios recibidos.', question: '¿Quieres comparar ingresos públicos, presión fiscal de los hogares o un impuesto concreto?', reply: 'Sí: los ingresos totales de las administraciones públicas equivalieron al 42,9% del PIB en 2025. Eso es un agregado nacional, no significa que cada hogar pague el 42,9% de su renta.', visualLabel: 'Los ingresos públicos agregados no son una factura doméstica', visuals: { key: { value: '42,9 %', label: 'Ingresos públicos sobre PIB', period: '2025' }, trend: { available: true, labels: ['2015','2017','2019','2021','2023','2025'], values: [38.4,37.9,39,42.8,42.1,42.9], label: 'Ingresos totales de las administraciones públicas', unit: '% del PIB' }, caveat: 'Es un agregado de todas las administraciones públicas. No describe cuánto paga cada hogar ni qué impuesto explica el resultado.' } },
  'gasto-publico-supera-45': { prompt: 'El gasto público de España supera el 45% del PIB', aliases: ['España gasta más del 45% del PIB','el gasto público supera el 45 por ciento','el Estado gasta más del 45% del PIB','el gasto de las administraciones supera el 45%','gasto público España'], propositions: ['El gasto total de las administraciones públicas equivalió al 45,3% del PIB en 2025.','El 45,3% del PIB se gasta en un único servicio o ministerio.','El porcentaje demuestra por sí solo que el gasto público es eficiente.'], concern: 'El gasto público agregado permite medir el tamaño total de los recursos utilizados por las administraciones, pero no explica cómo se distribuyen ni qué resultados producen.', supports: 'Eurostat registra gasto público equivalente al 45,3% del PIB en 2025, frente al 43,7% en 2015.', limit: 'La serie suma administraciones y partidas distintas. No identifica educación, sanidad, pensiones o inversión, ni mide por sí sola eficiencia o calidad.', question: '¿Quieres comparar gasto público total, un servicio concreto o el resultado de ese gasto?', reply: 'Sí: el gasto total de las administraciones públicas equivalió al 45,3% del PIB en 2025. Es un agregado nacional; no significa que un ministerio concreto gaste esa proporción ni demuestra por sí solo cómo funcionan los servicios.', visualLabel: 'El gasto agregado no muestra dónde se gasta ni qué resultado produce', visuals: { key: { value: '45,3 %', label: 'Gasto público total sobre PIB', period: '2025' }, trend: { available: true, labels: ['2015','2017','2019','2021','2023','2025'], values: [43.7,41,42,49.5,45.4,45.3], label: 'Gasto total de las administraciones públicas', unit: '% del PIB' }, caveat: 'El agregado no identifica partidas ni resultados. Para hablar de educación, sanidad o pensiones hace falta una serie específica.' } },
  'deficit-publico-baja-3': { prompt: 'El déficit público de España baja del 3% del PIB', aliases: ['España tiene un déficit inferior al 3%','el déficit público baja del 3 por ciento','el déficit del Estado es menor del 3%','España reduce el déficit público','déficit público España'], propositions: ['El déficit de las administraciones públicas fue del 2,4% del PIB en 2025.','Un déficit inferior al 3% significa que España ya no tiene deuda pública.','Un déficit menor demuestra por sí solo que la política económica es correcta.'], concern: 'Reducir el déficit es un cambio relevante en las cuentas públicas, pero no elimina la deuda acumulada ni resuelve por sí solo la discusión sobre el uso del gasto.', supports: 'Eurostat registra una necesidad de financiación del 2,4% del PIB en 2025, frente al 5,3% en 2015.', limit: 'El déficit es un flujo anual y no equivale a deuda, saldo de un hogar ni calidad de la política económica. En esta serie los valores negativos representan déficit.', question: '¿Quieres comparar déficit anual, deuda acumulada o el destino del gasto público?', reply: 'Sí: el déficit de las administraciones públicas fue del 2,4% del PIB en 2025, por debajo del 3%. Es un flujo anual: no significa que haya desaparecido la deuda acumulada ni que la política económica quede evaluada por una sola cifra.', visualLabel: 'Menos déficit no significa menos deuda acumulada', visuals: { key: { value: '−2,4 %', label: 'Necesidad de financiación pública sobre PIB', period: '2025' }, trend: { available: true, labels: ['2015','2017','2019','2021','2023','2025'], values: [-5.3,-3.1,-3.1,-6.7,-3.3,-2.4], label: 'Déficit público en España', unit: '% del PIB · déficit en valores negativos' }, caveat: 'La serie mide el flujo anual de déficit o superávit. No es la deuda acumulada y sus valores negativos representan déficit.' } },
  'sobrecarga-vivienda-baja': { prompt: 'La sobrecarga del coste de la vivienda ha bajado en España desde 2015', aliases: ['la sobrecarga de la vivienda ha bajado','menos personas sufren sobrecarga de vivienda','el esfuerzo de vivienda ha bajado','los gastos de vivienda pesan menos','el coste de la vivienda pesa menos'], propositions: ['La proporción de población con sobrecarga del coste de la vivienda bajó entre 2015 y 2025.','Quedar por debajo del umbral significa que la vivienda es asequible para todos.','La media nacional representa igual a todas las rentas y territorios.'], concern: 'El indicador ha mejorado, pero la dificultad de acceso puede seguir siendo intensa aunque un hogar no supere el umbral estadístico.', supports: 'La proporción pasó del 10,3% en 2015 al 7,2% en 2025, con un repunte al 9,9% en 2021.', limit: 'La sobrecarga mide costes superiores al 40% de la renta disponible equivalente; no resume toda la asequibilidad ni las diferencias territoriales.', question: '¿Quieres medir sobrecarga, acceso a una vivienda o esfuerzo en una renta y territorio concretos?', reply: 'Sí, la proporción bajó del 10,3% al 7,2% entre 2015 y 2025. Pero el indicador solo cuenta el umbral del 40% y una media nacional no demuestra que la vivienda sea asequible para todos.', visualLabel: 'Bajar un umbral no elimina toda la dificultad de vivienda', visuals: { key: { value: '7,2 %', label: 'Población en hogares con sobrecarga', period: '2025' }, trend: { available: true, labels: ['2015','2017','2019','2021','2023','2025'], values: [10.3,9.8,8.5,9.9,8.2,7.2], label: 'Sobrecarga del coste de la vivienda', unit: '% de la población' }, caveat: 'Eurostat usa un umbral del 40% de la renta disponible equivalente. No mide por sí solo calidad, acceso, territorio o renuncia a una vivienda adecuada.' } },
  'gasto-sanitario-habitante-sube': { prompt: 'España gasta más por habitante en sanidad que en 2015', aliases: ['España gasta más en sanidad por persona','el gasto sanitario por habitante ha subido','se gasta más en salud que en 2015','el gasto sanitario ha aumentado','España invierte más en sanidad'], propositions: ['El gasto sanitario corriente por habitante aumentó entre 2015 y 2023.','Gastar más por habitante demuestra que el sistema funciona mejor.','Todo el gasto de la serie procede del Gobierno central.'], concern: 'El gasto por habitante ha subido, pero el dinero empleado y el rendimiento del sistema son preguntas diferentes.', supports: 'Eurostat registra 2.148,72 € por habitante en 2015 y 2.857,25 € en 2023.', limit: 'Es gasto sanitario corriente total financiado por todos los esquemas y está expresado en euros corrientes; no mide por sí solo acceso, calidad o esperas.', question: '¿Quieres comparar gasto, resultados clínicos, acceso o listas de espera?', reply: 'Sí: el gasto sanitario corriente por habitante subió de 2.148,72 € en 2015 a 2.857,25 € en 2023. Es gasto total en euros corrientes, no una prueba automática de que el sistema funcione mejor.', visualLabel: 'Más gasto no equivale automáticamente a mejores resultados', visuals: { key: { value: '2.857 €', label: 'Gasto sanitario corriente por habitante', period: '2023' }, trend: { available: true, labels: ['2015','2017','2019','2021','2023'], values: [2148.72,2266.56,2451.99,2693.71,2857.25], label: 'Gasto sanitario corriente por habitante', unit: '€ por habitante · euros corrientes' }, caveat: 'La última observación de esta serie es 2023. El gasto total no mide por sí solo acceso, calidad, resultados clínicos o listas de espera.' } },
  'desigualdad-renta-baja': { prompt: 'La desigualdad de renta ha bajado en España desde 2015', aliases: ['la desigualdad de ingresos ha bajado','el Gini ha bajado','hay menos desigualdad de renta','la distribución de la renta ha mejorado','España es menos desigual'], propositions: ['El coeficiente de Gini de la renta disponible equivalente bajó entre 2015 y 2025.','Menor Gini significa que no existe pobreza.','El Gini muestra cuánto cambió la renta de cada grupo.'], concern: 'La desigualdad relativa ha bajado en esta medida, pero eso no borra la pobreza ni cuenta cómo vivió el cambio cada grupo.', supports: 'Eurostat registra un descenso del Gini de 34,6 en 2015 a 30,8 en 2025.', limit: 'El Gini resume la distribución: no equivale a pobreza, riqueza, igualdad territorial ni mejora de todos los hogares.', question: '¿Quieres comparar desigualdad, pobreza, renta de un grupo o riqueza acumulada?', reply: 'Sí, el Gini bajó de 34,6 en 2015 a 30,8 en 2025, lo que indica menos desigualdad relativa en esa medida. No significa que no haya pobreza ni que todos hayan mejorado igual.', visualLabel: 'Menos desigualdad relativa no equivale a ausencia de pobreza', visuals: { key: { value: '30,8', label: 'Coeficiente de Gini de la renta disponible', period: '2025' }, trend: { available: true, labels: ['2015','2017','2019','2021','2023','2025'], values: [34.6,34.1,33,33,31.5,30.8], label: 'Coeficiente de Gini de la renta disponible', unit: 'escala 0–100 · menor es menos desigualdad' }, caveat: 'El Gini es un resumen de la distribución. No mide por sí solo pobreza, riqueza acumulada ni la evolución de cada grupo.' } },
  'pib-real-sigue-creciendo': { prompt: 'El PIB real de España sigue creciendo', aliases: ['la economía española sigue creciendo','el PIB real sigue subiendo','España sigue creciendo económicamente','el PIB de España crece'], propositions: ['El PIB real creció interanualmente en el segundo trimestre de 2026.','El crecimiento agregado significa que todos los hogares están mejor.','La economía ha crecido sin ningún retroceso durante el periodo.'], concern: 'La actividad agregada sigue creciendo en la última observación, pero una familia puede seguir sufriendo precios, vivienda o salarios insuficientes.', supports: 'Eurostat registra un crecimiento interanual del PIB real del 2,7% en 2026-T2.', limit: 'El PIB mide actividad agregada: no demuestra bienestar individual, precios bajos, distribución de renta ni ausencia de retrocesos anteriores.', question: '¿Quieres comprobar PIB, renta disponible, coste de vida o la situación de un hogar?', reply: 'Sí: el PIB real creció un 2,7% interanual en el segundo trimestre de 2026. Eso no significa que todas las familias estén mejor ni que hayan desaparecido los problemas de vivienda, precios o salarios.', visualLabel: 'Actividad económica y bienestar familiar no son la misma medida', visuals: { key: { value: '+2,7 %', label: 'Crecimiento interanual del PIB real', period: '2026-T2' }, trend: { available: true, labels: ['2015-T1','2017-T1','2019-T1','2021-T1','2023-T1','2025-T1','2026-T2'], values: [3.6,2.4,2.4,-2.9,3.6,3.1,2.7], label: 'Crecimiento interanual del PIB real', unit: '%' }, caveat: 'El PIB real es una medida agregada de actividad. No demuestra que todos los hogares estén mejor ni que no haya problemas de precios, vivienda o empleo.' } },
  'viviendas-vacias': { prompt: 'Hay millones de viviendas vacías, así que no hace falta construir', aliases: ['viviendas vacias','casas vacias','3,8 millones','tres millones','construir','pisos vacios','vivienda vacia'], propositions: ['España tiene millones de viviendas clasificadas como vacías.','Esas viviendas están disponibles y habitables.','Están situadas donde se concentra la demanda.','Por tanto, construir no es necesario.'], concern: 'Movilizar viviendas vacías habitables puede ayudar, especialmente en mercados concretos.', supports: 'La cifra de viviendas clasificadas como vacías existe y justifica investigar su estado, ubicación y disponibilidad.', limit: 'La cifra nacional no indica cuántas pueden alquilarse mañana ni cuántas están en Madrid, Málaga, Barcelona u otros mercados tensionados.', question: '¿De qué municipio o mercado de vivienda estamos hablando?', reply: 'La cifra de viviendas vacías es real, pero no dice cuántas están habitables, disponibles y donde hace falta vivir. Movilizarlas ayuda; el total nacional no demuestra que construir sea innecesario.', visualLabel: 'El total nacional no mide la disponibilidad local', visuals: { key: { value: '3,8 M', label: 'Viviendas clasificadas como vacías', period: '2020' }, trend: { available: false, labels: [], values: [], label: 'Viviendas vacías disponibles en el tiempo', unit: 'No hay una serie comparable conectada' }, comparison: { labels: ['Precio nacional','Precio en Comunitat Valenciana','Precio en Madrid'], values: [12.9,14.3,13.6], label: 'Variación anual del precio de compraventa', unit: '% · 1T 2026' }, regionTopic: 'vivienda', caveat: 'La clasificación de vivienda vacía no informa por sí sola sobre habitabilidad, disponibilidad legal o localización exacta. La serie regional conectada mide precios, no viviendas vacías.' } },
  'empleo-record': { prompt: 'España tiene más empleo que nunca, así que el trabajo va bien', aliases: ['empleo record','trabajo record','nunca tanta gente trabajando','ocupados','empleo','trabajo va bien','paro'], propositions: ['España ha alcanzado un máximo histórico de personas ocupadas.','El máximo absoluto demuestra que el empleo es suficiente y de calidad.','El desempleo y la calidad del trabajo dejan de ser problemas.'], concern: 'Es relevante que haya más personas trabajando, pero una cifra récord puede convivir con paro, bajos salarios o empleos inestables.', supports: 'En el primer trimestre de 2026 había 22,293 millones de personas ocupadas, un máximo histórico.', limit: 'El máximo absoluto también refleja el crecimiento de la población y de la fuerza laboral. No mide por sí solo salarios, horas, estabilidad ni tasa de paro.', question: '¿Estamos hablando de cuántas personas trabajan o de si el empleo permite vivir mejor?', reply: 'Sí, hay un máximo histórico de ocupados. Pero eso no resuelve por sí solo la calidad del empleo: también hay que mirar paro, salarios, horas y continuidad.', visualLabel: 'Máximo de ocupación, no medida completa de calidad', visuals: { key: { value: '22,293 M', label: 'Personas ocupadas', period: '1T 2026' }, trend: { available: false, labels: [], values: [], label: 'Ocupación histórica', unit: 'No hay una serie temporal conectada' }, comparison: { labels: ['Ocupados','Tasa de paro'], values: [22.293,10.83], label: 'Ocupación y paro deben leerse juntos', unit: 'millones / % · 1T 2026' }, regionTopic: 'empleo', caveat: 'El máximo absoluto de ocupación no mide salarios, horas, estabilidad ni calidad del empleo. La serie autonómica conectada mide tasa de paro EPA, no calidad laboral.' } },
  'inmigrantes-ayudas': { prompt: 'Los inmigrantes reciben todas las ayudas', aliases: ['inmigrantes ayudas','extranjeros ayudas','paguitas para inmigrantes','ayudas para extranjeros'], propositions: ['Las personas inmigrantes pueden recibir prestaciones si cumplen sus requisitos.','La nacionalidad da prioridad general en las ayudas públicas.','Las ayudas explican por sí solas la situación de la vivienda.'], concern: 'La escasez de recursos públicos puede ser una preocupación legítima, pero “las ayudas” reúne prestaciones con reglas distintas.', supports: 'España terminó 2025 con alrededor de 3,1 millones de trabajadores extranjeros afiliados.', limit: 'La afiliación no demuestra quién recibe una ayuda ni si existe prioridad por nacionalidad. Harían falta el programa, sus requisitos y datos de adjudicación.', question: '¿De qué prestación, municipio y requisito concreto estamos hablando?', reply: 'Puede haber personas extranjeras que reciban ayudas, pero no basta con decir “los inmigrantes”: cada prestación tiene requisitos distintos y la afiliación no demuestra prioridad por nacionalidad.', visualLabel: 'Trabajar, recibir una prestación y tener prioridad son preguntas distintas', visuals: { key: { value: '3,1 M', label: 'Trabajadores extranjeros afiliados', period: 'Final de 2025' }, trend: { available: false, labels: [], values: [], label: 'Acceso a prestaciones por nacionalidad', unit: 'No hay una serie comparable conectada' }, caveat: 'Este dato es contexto sobre empleo, no una medición de beneficiarios, importes o prioridad en una prestación concreta.' } },
  'espana-impuestos-europa': { prompt: 'España es el país que más impuestos cobra de Europa', aliases: ['España tiene demasiados impuestos','infierno fiscal','impuestos más altos de Europa'], propositions: ['España recauda una proporción muy alta de la economía.','España es el país europeo que más impuestos cobra.','La presión fiscal agregada equivale a la factura de cada hogar.'], concern: 'La carga que nota cada persona puede ser alta aunque la recaudación total no sea la mayor de Europa.', supports: 'España se situaba alrededor del 37,3% del PIB frente a una media de la UE cercana al 39,4% en años comparables.', limit: 'La presión fiscal no mide la factura de cada hogar ni separa IRPF, cotizaciones, IVA y otros tributos.', question: '¿Quieres comparar recaudación total, impuestos sobre el trabajo o lo que paga un hogar concreto?', reply: 'España no es el país que más recauda de Europa como proporción del PIB, pero sí puede cargar mucho el empleo formal. Hay que distinguir la medida antes de comparar.', visualLabel: 'La presión fiscal agregada no es la factura de un hogar', visuals: { key: { value: '37,3 %', label: 'Recaudación aproximada sobre el PIB', period: 'Años comparables recientes' }, trend: { available: false, labels: [], values: [], label: 'Presión fiscal comparable', unit: 'La serie internacional necesita la misma definición y año' }, comparison: { labels: ['España','Media UE'], values: [37.3,39.4], label: 'Recaudación sobre PIB', unit: '% del PIB' }, caveat: 'La comparación depende del año y la definición. No convierte la media nacional en la factura fiscal de una familia.' } },
  'espana-mas-peligrosa': { prompt: 'España cada vez es más peligrosa', aliases: ['España es más insegura','hay más delincuencia que antes','ya no se puede salir a la calle'], propositions: ['La delincuencia general ha aumentado mucho.','Algunos delitos, como la cibercriminalidad, sí han crecido.','La media nacional describe igual todos los barrios.'], concern: 'Una experiencia local de inseguridad puede ser real aunque la tendencia nacional sea distinta.', supports: 'En 2025 la cibercriminalidad subió un 5,3% mientras la delincuencia convencional cayó un 0,2%.', limit: 'Los recuentos nacionales no descartan focos locales ni miden directamente la percepción individual de seguridad.', question: '¿Hablamos de qué delito, lugar y periodo?', reply: 'No hay una explosión general de delito callejero: la cibercriminalidad creció mientras la convencional bajó ligeramente. Para hablar de un barrio hay que mirar sus datos.', visualLabel: 'El delito no cambia igual en todas sus categorías', visuals: { key: { value: '+5,3 %', label: 'Variación de la cibercriminalidad', period: '2025' }, trend: { available: false, labels: [], values: [], label: 'Delincuencia por tipo y territorio', unit: 'Los recuentos nacionales no sustituyen una tasa local' }, caveat: 'La media nacional combina delitos distintos y no descarta experiencias locales graves.' } },
  'sanidad-colapsada': { prompt: 'La sanidad pública está colapsada', aliases: ['sanidad colapsada','listas de espera interminables','no hay médicos'], propositions: ['Las esperas y el acceso sanitario muestran deterioro.','El sistema sanitario ha dejado de tener capacidad clínica.','Una lista de espera resume todo el funcionamiento de la sanidad.'], concern: 'Esperar demasiado para recibir atención es un problema real aunque “colapso” describa más de una dimensión.', supports: '853.509 pacientes esperaban cirugía electiva al cierre de 2025.', limit: 'Una lista quirúrgica no resume resultados, atención primaria, salud mental, personal ni diferencias territoriales.', question: '¿Hablamos de cirugía, primaria, especialistas o salud mental?', reply: 'Hay un problema serio de acceso y demoras, pero una lista quirúrgica no demuestra que toda la sanidad esté colapsada. Conviene concretar el servicio y el territorio.', visualLabel: 'La espera es importante, pero no mide todo el sistema', visuals: { key: { value: '853.509', label: 'Pacientes en lista quirúrgica', period: 'Cierre de 2025' }, trend: { available: false, labels: [], values: [], label: 'Listas de espera por servicio y territorio', unit: 'La cifra nacional no sustituye el detalle territorial' }, caveat: 'El total de pacientes no informa por sí solo del tiempo individual, procedimiento o comunidad.' } },
  'paro-epa-registro': { prompt: 'El paro de la EPA y el registrado son la misma cifra', aliases: ['paro EPA y SEPE','paro registrado','la EPA infla el paro','paro real'], propositions: ['La EPA y el registro administrativo miden exactamente el mismo desempleo.','La EPA es una encuesta a hogares.','El paro registrado procede de personas inscritas como demandantes.'], concern: 'Las dos series intentan describir el desempleo, pero responden a definiciones y fuentes distintas.', supports: 'La EPA y el paro registrado pueden ofrecer niveles y evoluciones diferentes sin que una cifra sea automáticamente un error.', limit: 'No se puede elegir la serie que mejor encaje con un argumento y llamarla por sí sola “el paro real”.', question: '¿Qué medida, población y periodo quieres comparar?', reply: 'La EPA es una encuesta y el paro registrado es un registro administrativo: no cuentan exactamente lo mismo. Para compararlos hay que decir qué mide cada uno.', visualLabel: 'Dos medidas, dos definiciones', visuals: { key: { value: '2', label: 'Medidas que no deben confundirse', period: 'Actual' }, trend: { available: false, labels: [], values: [], label: 'EPA y paro registrado', unit: 'Definiciones distintas' }, caveat: 'Las diferencias entre ambas series no demuestran por sí solas que una esté manipulada.' } },
  'inflacion-baja-precios-no-bajan': { prompt: 'Si baja la inflación, bajan los precios', aliases: ['baja la inflación bajan los precios','desinflación','el IPC baja'], propositions: ['La tasa de inflación ha bajado.','El nivel general de precios está bajando.','Una familia concreta paga menos.'], concern: 'Que los precios suban más despacio no significa que vuelvan al nivel anterior.', supports: 'Una menor tasa de inflación puede coexistir con un nivel general de precios superior al del año anterior.', limit: 'La inflación media tampoco describe lo que paga cada hogar: alimentación, alquiler, energía y transporte pesan de forma distinta.', question: '¿Qué producto, periodo y gasto familiar quieres comparar?', reply: 'Que baje la inflación significa que los precios suben más despacio, no que estén bajando en general. Para saber si una familia paga menos hay que mirar sus gastos concretos.', visualLabel: 'Velocidad de subida y nivel de precios no son lo mismo', visuals: { key: { value: '≠', label: 'Desinflación no es deflación', period: 'Actual' }, trend: { available: false, labels: [], values: [], label: 'Evolución del IPC', unit: 'La tasa y el nivel son medidas distintas' }, caveat: 'El efecto sobre cada hogar depende de su cesta de consumo y del periodo comparado.' } },
  'precio-vivienda-sube': { prompt: 'La vivienda ya está bajando de precio', aliases: ['la vivienda baja','los pisos están bajando','el precio de la vivienda cae'], propositions: ['La vivienda está bajando en España.','Los precios pueden comportarse distinto por territorio y tipo de vivienda.','La media nacional describe cada barrio.'], concern: 'Puede haber excepciones locales, pero una afirmación nacional debe contrastarse con la serie nacional comparable.', supports: 'La serie nacional disponible no muestra una caída interanual en sus últimos periodos; alcanzó una variación del 12,9% en el primer trimestre de 2026.', limit: 'Una media nacional no describe cada barrio ni permite predecir cuándo cambiará el mercado.', question: '¿De qué ciudad, tipo de vivienda y periodo hablamos?', reply: 'La serie nacional no indica que la vivienda esté bajando: el último dato disponible muestra una subida interanual del 12,9%. Puede haber excepciones locales.', visualLabel: 'La tendencia nacional no elimina las diferencias locales', visuals: { key: { value: '+12,9 %', label: 'Variación interanual del precio', period: '1T 2026' }, trend: { available: false, labels: [], values: [], label: 'Precio de vivienda por territorio', unit: 'La media nacional no es un barrio' }, caveat: 'Los precios pueden divergir mucho entre comunidades, ciudades y tipos de vivienda.' } },
  'inmigrantes-patera': { prompt: 'La mayoría de inmigrantes llega en patera', aliases: ['pateras','todos llegan en barco','inmigración irregular'], propositions: ['Las llegadas irregulares representan la mayoría de la inmigración.','Las llegadas por mar y tierra son visibles y plantean retos de control.','Un flujo anual equivale a toda la población residente nacida fuera.'], concern: 'Las llegadas irregulares son visibles, pero no representan todo el fenómeno migratorio.', supports: 'En 2025 se registraron 36.775 llegadas irregulares frente a más de 10 millones de residentes nacidos en el extranjero.', limit: 'Los flujos y el stock de residentes miden poblaciones y periodos distintos y no deben sumarse.', question: '¿Hablamos de llegadas de un año o de personas que ya residen en España?', reply: 'Las pateras son muy visibles, pero no representan la vía de llegada de la mayoría: en 2025 hubo 36.775 llegadas irregulares y más de 10 millones de residentes nacidos fuera.', visualLabel: 'Un flujo anual no es toda la población migrante', visuals: { key: { value: '36.775', label: 'Llegadas irregulares registradas', period: '2025' }, trend: { available: false, labels: [], values: [], label: 'Flujos y población residente', unit: 'Medidas distintas: llegadas frente a stock' }, caveat: 'No deben compararse como si fueran la misma población: una cifra es un flujo anual y la otra un stock residente.' } },
  'airbnb-vivienda': { prompt: 'Airbnb es la causa de toda la crisis de vivienda', aliases: ['airbnb causa la crisis','pisos turísticos','alquiler vacacional','turismo y vivienda'], propositions: ['El alquiler turístico reduce la oferta residencial en algunos mercados.','Airbnb explica por sí solo la escasez nacional de vivienda.','El impacto es igual en todos los barrios y municipios.'], concern: 'El alquiler turístico puede agravar mercados locales muy tensionados, aunque no explica por sí solo toda la escasez nacional.', supports: 'La presión del alquiler turístico es especialmente relevante en barrios y municipios turísticos con poca oferta residencial.', limit: 'La evidencia disponible no convierte un impacto local en una causa única nacional ni mide por sí sola planificación, construcción o parque público.', question: '¿De qué ciudad o barrio hablamos y qué proporción de viviendas se destina a uso turístico?', reply: 'El alquiler turístico puede agravar mercados locales muy tensionados, pero no explica por sí solo la escasez nacional: también cuentan la oferta, la demanda, la planificación y el parque público.', visualLabel: 'Un impacto local no demuestra una causa única nacional', visuals: { key: { value: 'Local', label: 'Impacto más intenso en mercados turísticos', period: '2025–2026' }, trend: { available: false, labels: [], values: [], label: 'Vivienda turística y alquiler residencial', unit: 'Hace falta comparar el mercado local' }, caveat: 'Una media nacional no mide el daño de un barrio concreto ni permite atribuir toda la crisis a una sola plataforma.' } },
  'fijos-discontinuos': { prompt: 'Los fijos discontinuos son parados ocultos', aliases: ['fijo discontinuo parado','parados ocultos','maquillaje del paro','contratos fijos discontinuos'], propositions: ['Una persona fija discontinua puede pasar periodos sin actividad ni ingreso laboral.','Toda persona fija discontinua cumple automáticamente la definición estadística de desempleo.','La etiqueta contractual informa de la renta anual y los días trabajados.'], concern: 'Puede haber periodos de inactividad y pérdida de ingresos, pero la etiqueta contractual no equivale automáticamente a desempleo estadístico.', supports: 'El contrato fijo discontinuo mantiene una relación laboral indefinida aunque haya periodos sin actividad.', limit: 'La categoría no informa por sí sola de días trabajados, ingresos anuales ni de si la persona está buscando empleo durante la inactividad.', question: '¿Quieres medir desempleo estadístico, meses trabajados o ingresos anuales?', reply: 'Un fijo discontinuo no es automáticamente un parado oculto. La pregunta útil es cuántos días trabaja, qué ingreso anual obtiene y si busca empleo durante la inactividad.', visualLabel: 'Contrato, desempleo e ingreso anual son medidas distintas', visuals: { key: { value: 'No automáticamente', label: 'Equivale a paro estadístico', period: 'Definición vigente' }, trend: { available: false, labels: [], values: [], label: 'Fijos discontinuos y desempleo', unit: 'La etiqueta contractual no basta' }, caveat: 'La definición estadística y la situación laboral concreta requieren datos distintos.' } },
  'smi-destruye-empleo': { prompt: 'Subir el salario mínimo destruyó empleo', aliases: ['el SMI destruye empleo','salario mínimo y empleo','subir el salario mínimo'], propositions: ['Una subida fuerte del salario mínimo puede afectar de forma distinta a sectores y trabajadores.','Las subidas del salario mínimo destruyeron el empleo agregado.','La tendencia nacional descarta cualquier ajuste en grupos concretos.'], concern: 'Los efectos pueden concentrarse en sectores o trabajadores de baja productividad, pero eso no equivale a una destrucción agregada demostrada.', supports: 'El salario mínimo alcanzó 1.221 euros en 14 pagas en 2026 y el empleo agregado siguió creciendo tras las grandes subidas.', limit: 'La tendencia nacional no identifica el contrafactual ni descarta efectos concretos por sector, edad, territorio o productividad.', question: '¿Hablamos del empleo total o de un grupo y sector concreto?', reply: 'No se observa una destrucción agregada de empleo tras las subidas del SMI. Eso no descarta ajustes en sectores o grupos concretos: son preguntas distintas.', visualLabel: 'El total de empleo no resuelve el efecto en cada grupo', visuals: { key: { value: '1.221 €', label: 'Salario mínimo en 14 pagas', period: '2026' }, trend: { available: false, labels: [], values: [], label: 'Salario mínimo y empleo', unit: 'El efecto causal requiere comparación y contrafactual' }, caveat: 'Una evolución nacional no prueba qué habría ocurrido sin la subida ni elimina posibles efectos distributivos.' } },
  'economia-crece-coste-vida': { prompt: 'La economía crece, pero la vida sigue demasiado cara', aliases: ['la economía crece pero no se nota','el PIB sube y todo está más caro','crecimiento y coste de vida','España crece y la gente sigue peor'], propositions: ['El PIB y el empleo pueden crecer mientras los precios siguen aumentando.','Si la economía crece, todos los hogares están mejor.','Que el coste de vida siga alto demuestra que toda la economía está en recesión.'], concern: 'El crecimiento medio puede convivir con una experiencia difícil por alquileres, precios, deuda, renta y situación laboral.', supports: 'El PIB real creció un 2,7% interanual en el primer trimestre de 2026 mientras el IPC seguía midiendo variación de precios.', limit: 'El crecimiento medio no llega igual a todos los hogares y la inflación acumulada no implica que los precios vuelvan al nivel anterior.', question: '¿Quieres comparar PIB, precios, salarios o la renta disponible de un hogar concreto?', reply: 'La economía puede crecer y crear empleo mientras la compra y el alquiler siguen caros. Crecimiento, inflación acumulada y renta disponible son medidas distintas.', visualLabel: 'Crecimiento, inflación y bienestar no son la misma medida', visuals: { key: { value: '+2,7 %', label: 'Crecimiento interanual del PIB real', period: '1T 2026' }, trend: { available: false, labels: [], values: [], label: 'PIB, precios y renta disponible', unit: 'Una cifra nacional no describe todos los hogares' }, caveat: 'Que el PIB crezca no demuestra que todos los hogares estén mejor ni que el nivel de precios haya vuelto atrás.' } },
  'riesgo-pobreza-no-desaparece': { prompt: 'La pobreza ha desaparecido porque baja el riesgo AROPE', aliases: ['ya no hay pobreza en España','el AROPE demuestra que no hay pobreza','la pobreza está desapareciendo','baja AROPE'], propositions: ['La tasa AROPE ha bajado desde 2021.','AROPE equivale a una medida única de pobreza extrema.','Una caída de la tasa significa que el problema ha desaparecido.'], concern: 'Mejorar una tasa es relevante, pero no significa que la pobreza o la exclusión hayan desaparecido.', supports: 'La tasa AROPE pasó del 27,8% en 2021 al 25,7% en 2025.', limit: 'AROPE combina indicadores de riesgo de pobreza o exclusión y no resume todas las formas de privación ni la experiencia de cada hogar.', question: '¿Qué medida de pobreza quieres comparar: ingresos, privación material o exclusión social?', reply: 'El riesgo AROPE ha bajado, pero sigue afectando al 25,7% de la población. Mejorar no significa que el problema haya desaparecido.', visualLabel: 'Bajar una tasa no equivale a eliminar el problema', visuals: { key: { value: '25,7 %', label: 'Tasa AROPE', period: '2025' }, trend: { available: true, labels: ['2021','2022','2023','2024','2025'], values: [27.8,26,26.5,25.8,25.7], label: 'Evolución de la tasa AROPE', unit: '% de la población' }, caveat: 'AROPE es una medida compuesta de riesgo de pobreza o exclusión; no equivale a una única medida de pobreza extrema.' } },
  'inmigrantes-pensiones': { prompt: 'Los inmigrantes pagarán nuestras pensiones', aliases: ['inmigración y pensiones','los inmigrantes pagan las pensiones','cotizaciones de inmigrantes','envejecimiento e inmigración'], propositions: ['Más trabajadores jóvenes pueden aumentar cotizaciones y retrasar el deterioro demográfico.','La inmigración hace sostenible por sí sola el sistema de reparto durante décadas.','Las cotizaciones dependen solo del número de trabajadores y no de salarios o productividad.'], concern: 'La inmigración puede aportar cotizantes y tiempo, pero la sostenibilidad también depende de empleo, salarios, productividad y reformas.', supports: 'La llegada de trabajadores jóvenes puede aliviar parcialmente el envejecimiento y aumentar cotizaciones en el corto plazo.', limit: 'Las personas inmigrantes también envejecen y la inmigración no sustituye por sí sola la productividad, los salarios ni la reforma del sistema.', question: '¿Hablamos del efecto a corto plazo sobre cotizaciones o de la sostenibilidad a varias décadas?', reply: 'La inmigración aporta cotizantes y tiempo, pero no sustituye productividad, empleo, salarios y reformas del sistema de pensiones.', visualLabel: 'Alivio demográfico no es solución única', visuals: { key: { value: 'Parcial', label: 'Aportación al sistema de reparto', period: '2025–2026' }, trend: { available: false, labels: [], values: [], label: 'Población, empleo y pensiones', unit: 'La sostenibilidad depende de varias variables' }, caveat: 'El efecto fiscal y demográfico cambia con edad, salario, empleo, residencia y derechos futuros.' } },
  'paro-espana-supera-ue': { prompt: 'España tiene más paro que la media de la Unión Europea', aliases: ['España tiene más desempleo que Europa','el paro español supera la media europea','España está peor que la UE en paro','la tasa de paro de España es mayor que la europea'], propositions: ['En 2025 España tuvo un 10,5% de desempleo y la UE-27 un 6,0%.','La diferencia frente a la media europea demuestra por sí sola su causa.','La tasa anual comparable es idéntica al paro registrado.'], concern: 'España mantiene una brecha desfavorable frente a la media europea, pero compararla no basta para explicar sus causas ni la experiencia de cada persona.', supports: 'Eurostat registra 10,5% en España frente a 6,0% en la UE-27 en 2025.', limit: 'Es una tasa anual comparable de la población activa de 15 a 74 años. No es el paro registrado ni mide por sí sola duración, territorio o calidad del empleo.', question: '¿Quieres comparar la tasa anual, el paro registrado, la duración o el empleo por edad y territorio?', reply: 'Sí: en 2025 España registró un 10,5% de paro frente al 6,0% de media en la UE-27. Es una comparación anual comparable, pero no explica por sí sola las causas.', visualLabel: 'España y la media UE en una misma definición', visuals: { key: { value: '+4,5 p.p.', label: 'Brecha frente a la media UE-27', period: '2025' }, trend: { available: false, labels: [], values: [], label: 'Desempleo comparable por país', unit: 'Tasa anual · población activa de 15–74' }, comparison: { labels: ['España','UE-27'], values: [10.5,6], label: 'Tasa de desempleo comparable', unit: '% de la población activa · 2025' }, caveat: 'La comparación no establece la causa ni sustituye otras medidas del mercado laboral.' } },
  'deuda-publica-supera-100': { prompt: 'La deuda pública de España supera el 100% del PIB', aliases: ['España tiene una deuda pública superior al 100% del PIB','la deuda de España supera el 100 por cien','la deuda pública sigue por encima del PIB','España debe más de un año de PIB'], propositions: ['La deuda pública equivalió al 100,7% del PIB en 2025.','La deuda pública es una factura que cada hogar debe pagar en la misma proporción.','Superar el 100% del PIB demuestra por sí solo que España no puede sostener la deuda.'], concern: 'La deuda acumulada sigue siendo elevada aunque haya bajado desde el máximo de 2020; su sostenibilidad depende de más variables que una sola ratio.', supports: 'Eurostat registra una deuda bruta consolidada de las administraciones públicas del 100,7% del PIB en 2025.', limit: 'Es un stock acumulado comparado con el PIB anual. No equivale al déficit de un año, a una factura inmediata o a la deuda de cada familia.', question: '¿Quieres comparar deuda acumulada, déficit anual, intereses o el origen del gasto?', reply: 'Sí: la deuda pública equivalía al 100,7% del PIB en 2025. Es una ratio de deuda acumulada, no el déficit de un año ni la deuda de cada hogar.', visualLabel: 'Deuda acumulada y déficit anual son medidas distintas', visuals: { key: { value: '100,7 %', label: 'Deuda pública sobre PIB', period: '2025' }, trend: { available: true, labels: ['2015','2017','2019','2020','2022','2024','2025'], values: [102.5,101.2,97.7,119.3,109.3,101.6,100.7], label: 'Deuda bruta consolidada de las administraciones públicas', unit: '% del PIB' }, caveat: 'La ratio no decide por sí sola la sostenibilidad ni equivale a la deuda de cada hogar.' } },
  'paro-epa-supera-10': { prompt: 'La tasa de paro de la EPA sigue por encima del 10%', aliases: ['el paro de la EPA supera el 10%','la EPA todavía marca más de un 10% de paro','el desempleo EPA sigue por encima del 10%','el paro real está por encima del 10%'], propositions: ['La EPA mantiene una tasa de paro superior al 10%.','La tasa de la EPA y el paro registrado cuentan exactamente la misma población.','La tasa nacional describe la situación de cada hogar.'], concern: 'La EPA confirma que el desempleo sigue siendo elevado, pero su denominador y método no son los del registro administrativo.', supports: 'La EPA sitúa la tasa de paro española por encima del 10% en el primer trimestre de 2026.', limit: 'La tasa usa la población activa como denominador y no describe por sí sola territorio, hogar, sector o calidad del empleo.', question: '¿Quieres comparar la tasa EPA, el paro registrado o la situación laboral de un territorio concreto?', reply: 'Sí: la EPA mantiene el paro por encima del 10%. Es una tasa sobre la población activa y no es la misma medida que el paro registrado.', visualLabel: 'La tasa EPA y el registro administrativo responden preguntas distintas', visuals: { key: { value: '>10 %', label: 'Tasa de paro EPA', period: '1T 2026' }, trend: { available: false, labels: [], values: [], label: 'Desempleo por medida y territorio', unit: 'La tasa nacional no describe cada hogar' }, caveat: 'El denominador es la población activa; no incluye a quienes no trabajan ni buscan trabajo.' } },
  'brecha-salarial-genero-no-es-mito': { prompt: 'La brecha salarial de género es un mito', aliases: ['la brecha salarial de género no existe','la brecha salarial es un invento','mujeres y hombres cobran lo mismo','brecha salarial de genero mito'], propositions: ['El INE observó diferencias medias de salario entre mujeres y hombres en 2022.','Una brecha salarial agregada demuestra por sí sola discriminación directa.','La media anual compara exactamente las mismas jornadas, ocupaciones y trayectorias.'], concern: 'Los datos muestran una diferencia salarial media, pero separar composición del empleo y discriminación requiere más que repetir un promedio.', supports: 'El INE registró 24.359,82 euros de salario anual medio para mujeres y 29.381,84 para hombres en 2022; la brecha no ajustada por hora fue del 9,0%.', limit: 'La brecha no ajustada no compara automáticamente el mismo trabajo: hay que considerar jornada, ocupación, sector, antigüedad, responsabilidades y trayectoria.', question: '¿Quieres comparar salario anual, salario por hora o una ocupación y jornada concretas?', reply: 'No es correcto decir que la brecha salarial sea un mito: el INE observa diferencias medias y una brecha no ajustada por hora del 9,0%. Pero ese promedio tampoco demuestra por sí solo discriminación; hay que comparar ocupación, jornada, sector y trayectoria.', visualLabel: 'Diferencia media y causa de la diferencia son preguntas distintas', visuals: { key: { value: '9,0 %', label: 'Brecha salarial no ajustada por hora', period: '2022' }, trend: { available: false, labels: [], values: [], label: 'Brecha salarial y sus posibles componentes', unit: 'El promedio no identifica por sí solo la causa' }, comparison: { labels: ['Salario anual · mujeres','Salario anual · hombres'], values: [24359.82,29381.84], label: 'Salario medio anual · 2022', unit: 'euros por trabajador' }, caveat: 'La brecha no ajustada describe una diferencia media; no equivale automáticamente a discriminación por el mismo trabajo.' } },
  'ocupacion-aumenta-t2-2026': { prompt: 'España ganó 486.000 ocupados en el segundo trimestre de 2026', aliases: ['se crearon 486000 empleos en el segundo trimestre','España ganó 486.000 empleos','la ocupación subió en 486000 personas','hay 22,779 millones de ocupados'], propositions: ['La EPA registró 486.000 ocupados más en el segundo trimestre de 2026.','El aumento de ocupación demuestra que todo el empleo es estable y suficiente.','La cifra nacional describe por igual a cada territorio y hogar.'], concern: 'La ocupación aumentó con fuerza en el trimestre, pero una cifra nacional de personas ocupadas no resume la calidad, salario, horas o seguridad económica del trabajo.', supports: 'El INE registró 486.000 ocupados más, hasta 22.779.000, en el segundo trimestre de 2026.', limit: 'La ocupación trimestral no mide por sí sola salario, horas, estabilidad, productividad, territorio o calidad del empleo.', question: '¿Quieres comparar ocupación, paro, salario o calidad del empleo?', reply: 'Sí: la EPA registró 486.000 ocupados más en el segundo trimestre de 2026, hasta 22,779 millones. Es una mejora de ocupación, pero no demuestra por sí sola que todo el empleo sea estable o de calidad.', visualLabel: 'Más ocupación no equivale automáticamente a mejor empleo', visuals: { key: { value: '+486.000', label: 'Cambio trimestral de ocupación', period: '2T 2026' }, trend: { available: false, labels: [], values: [], label: 'Ocupación, paro y calidad del empleo', unit: 'Un aumento trimestral no mide por sí solo la experiencia laboral' }, comparison: { labels: ['Ocupados nuevos','Paro reducido','Ocupados totales'], values: [486000,213300,22779000], label: 'EPA · variación y nivel', unit: 'personas · 2T 2026' }, caveat: 'La ocupación absoluta debe leerse junto con población activa, desempleo, horas, salarios y estabilidad.' } },
  'paro-epa-t2-2026-baja-10': { prompt: 'La tasa de paro de la EPA bajó del 10% en el segundo trimestre de 2026', aliases: ['el paro bajó del 10%','la tasa de paro está por debajo del 10%','el desempleo EPA bajó del diez por ciento','paro EPA segundo trimestre 2026'], propositions: ['La EPA situó la tasa de paro en el 9,87% en el segundo trimestre de 2026.','La tasa representa a toda la población sin empleo, no solo a la población activa.','Bajar del 10% significa que el desempleo y la precariedad han dejado de ser problemas.'], concern: 'La tasa de paro bajó de un umbral relevante, pero sigue habiendo millones de personas desempleadas y la tasa no mide por sí sola la calidad del trabajo.', supports: 'El INE registró una tasa de paro del 9,87% en el segundo trimestre de 2026, con 2.495.300 personas desempleadas.', limit: 'La tasa usa la población activa como denominador. No describe por sí sola duración del desempleo, salarios, estabilidad, hogares ni diferencias territoriales.', question: '¿Quieres comparar el trimestre, el paro registrado o la calidad y duración del empleo?', reply: 'Sí: la EPA situó el paro en el 9,87% en el segundo trimestre de 2026. Es una tasa sobre la población activa; no significa que haya desaparecido el desempleo ni que todo el empleo sea estable.', visualLabel: 'Bajar del 10% no equivale a resolver el desempleo', visuals: { key: { value: '9,87 %', label: 'Tasa de paro EPA', period: '2T 2026' }, trend: { available: true, labels: ['1T 2026','2T 2026'], values: [10.83,9.87], label: 'Tasa de paro de la EPA', unit: '% de la población activa' }, caveat: 'La tasa nacional trimestral no muestra por sí sola duración, calidad, salarios, hogares ni diferencias territoriales.' } },
  'precios-hoteles-sube-junio-2026': { prompt: 'Los hoteles subieron precios aunque las pernoctaciones bajaron en junio de 2026', aliases: ['los hoteles son más caros aunque reciben menos turistas','el precio de los hoteles sube y las pernoctaciones bajan','los hoteles subieron un 5,6% en junio','el turismo hotelero bajó en junio de 2026'], propositions: ['El índice de precios hoteleros subió un 5,6% interanual en junio de 2026.','Las pernoctaciones hoteleras bajaron un 0,9% respecto a junio de 2025.','Estos datos demuestran que todo el turismo está cayendo o que explican la vivienda local.'], concern: 'Los hoteles pudieron cobrar más y registrar ligeramente menos pernoctaciones al mismo tiempo, pero ese dato mensual no resume todo el turismo ni la vivienda de cada destino.', supports: 'El INE registró un +5,6% en precios hoteleros y un -0,9% en pernoctaciones en junio de 2026.', limit: 'La encuesta hotelera no mide por sí sola apartamentos turísticos, visitas sin noche, alquileres residenciales ni una tendencia estructural de un solo mes.', question: '¿Quieres comprobar precios hoteleros, volumen de visitantes, alquiler turístico o vivienda residencial?', reply: 'En junio ocurrió algo concreto: los precios hoteleros subieron un 5,6% y las pernoctaciones bajaron un 0,9%. Es compatible con hoteles más caros y algo menos de noches, pero no mide todo el turismo ni explica por sí solo la vivienda.', visualLabel: 'Precio hotelero y volumen de noches pueden moverse distinto', visuals: { key: { value: '+5,6 %', label: 'Índice de precios hoteleros', period: 'Junio 2026' }, trend: { available: false, labels: [], values: [], label: 'Precios, pernoctaciones y facturación hotelera', unit: 'Indicadores distintos del sector hotelero' }, comparison: { labels: ['Precios hoteleros','Pernoctaciones','Facturación por habitación'], values: [5.6,-0.9,5.8], label: 'Variación interanual · junio 2026', unit: '%' }, caveat: 'La comparación usa indicadores hoteleros distintos y un solo mes; no equivale a una medida de todo el turismo ni de la vivienda.' } },
  'paro-historico': { prompt: 'El paro está en mínimos históricos', aliases: ['paro mínimo histórico','paro más bajo de la historia','SEPE y EPA','desempleo en mínimos'], propositions: ['El paro registrado está en un nivel muy bajo.','La EPA y el registro administrativo miden exactamente lo mismo.','Una cifra baja en el registro significa que el desempleo ha dejado de ser un problema.'], concern: 'El paro registrado puede estar en mínimos de una serie mientras la EPA mide otra población y una tasa todavía superior al 10%.', supports: 'El paro registrado está en su nivel más bajo desde antes de la crisis financiera.', limit: 'La EPA todavía mide una tasa superior al 10% y el registro administrativo responde a otra definición.', question: '¿Qué estadística y qué periodo quieres comparar: EPA o paro registrado?', reply: 'El paro registrado está muy bajo, pero la EPA todavía sitúa el desempleo por encima del 10%. Hay que decir qué estadística se usa.', visualLabel: 'Dos series de desempleo, no una sola cifra', visuals: { key: { value: '>10 %', label: 'Tasa de paro EPA citada', period: '2026' }, trend: { available: false, labels: [], values: [], label: 'EPA y paro registrado', unit: 'Definiciones y poblaciones distintas' }, caveat: 'Una serie administrativa no puede sustituir a una encuesta de hogares ni viceversa.' } },
  'espera-media-baja-listas-resueltas': { prompt: 'Si baja la espera media quirúrgica, las listas ya están resueltas', aliases: ['baja la espera media sanidad resuelta','listas de espera resueltas','menos días de espera significa que no hay lista','la sanidad funciona porque baja la espera'], propositions: ['Una reducción de la espera media puede ser una mejora real.','La media informa de cuántas personas siguen esperando y cuánto espera cada una.','Si baja la media, las listas están resueltas.'], concern: 'La espera media puede mejorar mientras persisten bolsas de pacientes con demoras largas.', supports: 'La espera media quirúrgica pasó de 126 días en diciembre de 2024 a 121 días en diciembre de 2025, mientras 853.509 pacientes seguían en lista.', limit: 'Una media no informa por sí sola de la distribución de las demoras, el número de pacientes por procedimiento ni las diferencias territoriales.', question: '¿Quieres mirar días de espera, número de pacientes o el procedimiento y territorio concretos?', reply: 'Que baje la espera media es una mejora, pero no significa que las listas estén resueltas. También hay que mirar cuántas personas esperan y cuánto tiempo.', visualLabel: 'Una media puede bajar mientras persisten esperas largas', visuals: { key: { value: '853.509', label: 'Pacientes en lista quirúrgica', period: 'Cierre de 2025' }, trend: { available: true, labels: ['Dic. 2024','Dic. 2025'], values: [126,121], label: 'Espera media quirúrgica', unit: 'días' }, caveat: 'La media no muestra la distribución de las esperas ni sustituye el detalle por procedimiento y territorio.' } },
  'fondos-vivienda': { prompt: 'Los fondos de inversión causan la crisis de vivienda', aliases: ['fondos buitre','fondos de inversión vivienda','Blackstone causa la crisis','los fondos son los dueños de los pisos'], propositions: ['Los grandes propietarios pueden influir en mercados locales.','Los fondos explican por sí solos la crisis nacional de vivienda.','La propiedad institucional tiene el mismo peso en todos los territorios.'], concern: 'La concentración de propiedad puede ser importante en barrios o promociones concretas, aunque no basta para explicar todo el mercado nacional.', supports: 'Las personas físicas poseen aproximadamente el 92% de las viviendas principales en alquiler analizadas.', limit: 'La cuota nacional no descarta poder local, prácticas abusivas ni diferencias entre mercados.', question: '¿Hablamos de la propiedad nacional o de un barrio, empresa y mercado concreto?', reply: 'Los fondos pueden tener mucho peso en algunos mercados, pero no explican por sí solos la crisis nacional: la gran mayoría del alquiler analizado está en manos de personas físicas.', visualLabel: 'Peso nacional y poder local no son la misma medida', visuals: { key: { value: '≈92 %', label: 'Viviendas principales en alquiler de personas físicas', period: 'Último dato analizado' }, trend: { available: false, labels: [], values: [], label: 'Propiedad del alquiler por territorio', unit: 'La media nacional puede ocultar concentraciones locales' }, caveat: 'Una cuota nacional pequeña no descarta poder de mercado o comportamientos abusivos en zonas concretas.' } },
  'construir-vivienda': { prompt: 'Basta con construir más vivienda', aliases: ['hay que construir más casas','construir vivienda arregla el problema','más oferta de vivienda','construir más pisos'], propositions: ['Las zonas con más hogares necesitan ampliar la oferta.','Cualquier vivienda nueva será asequible para la población local.','Construir más por sí solo resuelve la crisis.'], concern: 'Aumentar la oferta puede ser necesario, pero la ubicación, el precio y el régimen de uso determinan quién puede acceder.', supports: 'En mercados con crecimiento de hogares, añadir oferta y acelerar la construcción puede aliviar la presión.', limit: 'Una vivienda nueva no es automáticamente asequible: también importan el precio, el uso turístico, la protección permanente y el lugar donde se construye.', question: '¿Dónde se construiría, para quién y con qué precio o régimen?', reply: 'Construir más puede ser necesario, pero no basta decir “más vivienda”: importa dónde se hace, para quién, a qué precio y si queda disponible de forma permanente.', visualLabel: 'Cantidad sin ubicación ni precio no garantiza acceso', visuals: { key: { value: 'Más oferta', label: 'Puede aliviar mercados con más hogares', period: 'Medida estructural' }, trend: { available: false, labels: [], values: [], label: 'Hogares, viviendas terminadas y precios', unit: 'Hay que comparar la escala local' }, caveat: 'La oferta de lujo o turística no sustituye automáticamente a la vivienda asequible permanente.' } },
  'empleo-record-calidad': { prompt: 'Tener más personas ocupadas demuestra que todo el empleo es de calidad', aliases: ['más empleo significa buen empleo','récord de ocupación y precariedad','todo el empleo creado es bueno','más ocupados mejor trabajo'], propositions: ['España supera los 22 millones de personas ocupadas.','Un máximo absoluto demuestra que todo el empleo es de calidad.','La ocupación informa por sí sola de salario, horas y estabilidad.'], concern: 'Que más personas trabajen es una mejora relevante, pero no responde por sí sola a si el empleo permite vivir mejor.', supports: 'En el primer trimestre de 2026 había 22,293 millones de personas ocupadas.', limit: 'La ocupación no mide por sí sola horas, salario anual, continuidad, jornada involuntaria ni seguridad económica.', question: '¿Quieres medir cuántas personas trabajan o si ese trabajo permite vivir con estabilidad?', reply: 'Hay más personas trabajando que nunca, pero eso no demuestra que todo el empleo sea bueno. Para medir calidad hacen falta salario, horas, continuidad y seguridad económica.', visualLabel: 'Récord de ocupación, no medida completa de calidad', visuals: { key: { value: '22,293 M', label: 'Personas ocupadas', period: '1T 2026' }, trend: { available: false, labels: [], values: [], label: 'Ocupación y calidad del empleo', unit: 'La cifra absoluta no mide salarios ni estabilidad' }, comparison: { labels: ['Ocupados','Tasa de paro'], values: [22.293,10.83], label: 'Dos dimensiones del mercado laboral', unit: 'millones / % · 1T 2026' }, caveat: 'Más ocupados puede coexistir con paro, bajos salarios o jornadas insuficientes.' } },
  'cibercriminalidad-crece': { prompt: 'La cibercriminalidad crece más que la delincuencia convencional', aliases: ['delincuencia digital crece','fraude online aumenta','hay más delitos por internet','cibercrimen'], propositions: ['La cibercriminalidad crece más que la delincuencia convencional en la serie citada.','El crecimiento digital equivale a más inseguridad física en la calle.','Todos los delitos tienen la misma evolución.'], concern: 'Los delitos digitales pueden estar creciendo aunque la experiencia de inseguridad física siga otra tendencia.', supports: 'La fuente registra un aumento del 4,8% para la cibercriminalidad frente al 0,2% para el resto de la criminalidad.', limit: 'La cibercriminalidad incluye fenómenos distintos, como fraude y delitos informáticos, y no demuestra por sí sola que España sea más peligrosa en todos los entornos.', question: '¿Hablamos de fraude digital, delitos callejeros o percepción de seguridad?', reply: 'Sí, los delitos digitales crecen más en la serie citada. Eso describe un cambio en el tipo de delincuencia, no una explosión general de inseguridad física.', visualLabel: 'Cambiar el tipo de delito no equivale a una explosión general', visuals: { key: { value: '+4,8 %', label: 'Variación de la cibercriminalidad', period: 'Periodo de la fuente' }, trend: { available: false, labels: [], values: [], label: 'Delincuencia digital y convencional', unit: 'Son categorías distintas' }, comparison: { labels: ['Cibercriminalidad','Resto'], values: [4.8,0.2], label: 'Variación registrada', unit: '% · periodo de la fuente' }, caveat: 'Los recuentos digitales y convencionales no sustituyen una medición de la seguridad percibida en un barrio.' } },
  'espana-pobreza-cuarta-parte': { prompt: 'Uno de cada cuatro españoles vive en pobreza', aliases: ['una de cada cuatro personas pobreza','España está llena de pobres','AROPE una de cada cuatro','pobreza absoluta España'], propositions: ['El 25,7% estaba en riesgo de pobreza o exclusión AROPE.','Toda esa población vive en pobreza absoluta.','Todas las personas incluidas tienen la misma intensidad de privación.'], concern: 'El riesgo de pobreza o exclusión es un problema material importante, pero el indicador no describe una única situación de pobreza extrema.', supports: 'El 25,7% de la población estaba en riesgo de pobreza o exclusión según AROPE.', limit: 'AROPE combina pobreza relativa, carencia material y social severa o baja intensidad laboral; la cifra no equivale a indigencia para toda esa población.', question: '¿Quieres hablar de riesgo AROPE, pobreza relativa o carencia material severa?', reply: 'Una de cada cuatro personas estaba en riesgo de pobreza o exclusión según AROPE, pero eso no significa que todas vivan en indigencia: el indicador combina situaciones distintas.', visualLabel: 'Riesgo de pobreza no es una sola intensidad de privación', visuals: { key: { value: '25,7 %', label: 'Personas en riesgo de pobreza o exclusión', period: 'Último dato disponible' }, trend: { available: false, labels: [], values: [], label: 'AROPE y sus componentes', unit: 'El indicador combina varias dimensiones' }, caveat: 'La tasa AROPE debe leerse junto a sus componentes y no como una medida de pobreza absoluta idéntica para todas las personas.' } },
  'politica-no-es-mayoria': { prompt: 'La política es la preocupación de la mayoría de españoles', aliases: ['la mayoría está preocupada por la política','política principal problema mayoría','todos están hartos de la política','la política es el mayor problema'], propositions: ['La política aparece entre las preocupaciones de las encuestas.','La política es la preocupación de una mayoría absoluta.','Una categoría agrupada equivale a una respuesta individual.'], concern: 'La política puede ser una preocupación muy visible sin que una mayoría absoluta la señale como primera preocupación.', supports: 'En el cálculo reproducido del Barómetro de abril de 2026, política general representó el 13,9% de las menciones al sumar posiciones.', limit: 'El porcentaje depende de la pregunta, las categorías agrupadas y de si se mide la primera respuesta o cualquier posición.', question: '¿Estamos midiendo la primera preocupación, cualquier mención o una categoría agrupada?', reply: 'La política preocupa y aparece en las encuestas, pero decir que es la preocupación de la mayoría exagera el dato: hay que mirar la pregunta y cómo se cuentan las respuestas.', visualLabel: 'Una categoría visible no equivale a mayoría absoluta', visuals: { key: { value: '13,9 %', label: 'Política general en menciones agrupadas', period: 'Barómetro abril 2026' }, trend: { available: false, labels: [], values: [], label: 'Preocupaciones ciudadanas', unit: 'La métrica depende de la pregunta y la codificación' }, caveat: 'Las encuestas pueden medir primera respuesta, cualquier posición o categorías agrupadas: no son intercambiables.' } },
  'precio-vivienda-caera': { prompt: 'La vivienda acabará cayendo como en 2008', aliases: ['la vivienda va a caer como en 2008','otra burbuja inmobiliaria','los pisos se hundirán','la vivienda bajará pronto'], propositions: ['Los precios de la vivienda podrían corregir.','El mercado actual reproduce las condiciones de 2008.','La próxima caída puede predecirse con certeza.'], concern: 'Una corrección de precios es posible, pero el escenario actual no es idéntico al de 2008 y una predicción no es un hecho comprobado.', supports: 'Los precios pueden corregir y algunos compradores pueden haber pagado de más.', limit: 'La evidencia disponible no permite saber cuándo ocurrirá una caída ni demuestra que exista la misma combinación de sobreconstrucción, crédito débil y apalancamiento que precedió a 2008.', question: '¿Qué indicador, fecha y magnitud permitirían comprobar esta predicción?', reply: 'Una corrección es posible, pero 2026 no reproduce exactamente 2008: hoy pesa más una escasez localizada que una sobreconstrucción financiada con crédito débil.', visualLabel: 'Una predicción necesita fecha, indicador y condición', visuals: { key: { value: 'No seguro', label: 'Resultado futuro todavía no comprobable', period: 'Predicción' }, trend: { available: false, labels: [], values: [], label: 'Precios, crédito y construcción', unit: 'Una coincidencia histórica no garantiza el mismo desenlace' }, caveat: 'Para evaluar la predicción hay que fijar un horizonte, una serie comparable y una magnitud de caída.' } },
  'reforma-precariedad': { prompt: 'La reforma laboral acabó con la precariedad', aliases: ['la reforma laboral terminó con la precariedad','ya no hay contratos precarios','los fijos solucionaron la precariedad','reforma laboral y temporalidad'], propositions: ['La reforma redujo con claridad la temporalidad contractual.','La reducción de contratos temporales eliminó toda la precariedad.','El tipo de contrato mide por sí solo la seguridad económica.'], concern: 'Reducir la temporalidad es una mejora importante, pero la precariedad también depende de horas, salario, continuidad y progresión.', supports: 'La contratación indefinida ganó un peso que antes era inusual y la temporalidad contractual se redujo.', limit: 'Persisten pocas horas, salarios bajos, discontinuidad, rotación y falta de progresión: el tipo de contrato no mide por sí solo la seguridad económica.', question: '¿Quieres medir temporalidad, salario anual, horas o continuidad real?', reply: 'La reforma redujo temporalidad, pero no toda precariedad. Para medir seguridad hacen falta horas, ingreso anual, continuidad y posibilidades de progresión.', visualLabel: 'Contrato indefinido y seguridad económica no son sinónimos', visuals: { key: { value: 'Menos temporalidad', label: 'Cambio claro en la contratación', period: 'Tras la reforma laboral' }, trend: { available: false, labels: [], values: [], label: 'Temporalidad, horas y salarios', unit: 'La etiqueta contractual no resume toda la experiencia laboral' }, caveat: 'Una persona puede tener contrato indefinido y seguir sufriendo ingresos insuficientes, pocas horas o discontinuidad.' } },
  'record-empleo-no-resuelve-paro': { prompt: 'Un récord de ocupación significa que el paro ya está resuelto', aliases: ['récord de empleo significa pleno empleo','si hay más ocupados no hay paro','el paro está resuelto','más empleo acaba con el desempleo'], propositions: ['España superó los 22 millones de personas ocupadas.','El máximo de ocupación significa que el desempleo dejó de ser un problema.','Más ocupación y desempleo son medidas incompatibles.'], concern: 'Puede haber más personas trabajando y seguir existiendo mucho desempleo al mismo tiempo.', supports: 'España superó los 22 millones de personas ocupadas en la EPA.', limit: 'La tasa de paro seguía por encima del 10% y el máximo absoluto de ocupación también refleja el crecimiento de la población activa.', question: '¿Quieres comparar ocupación absoluta, tasa de paro o calidad del empleo?', reply: 'Hay un récord de ocupación, pero el paro no está resuelto: la EPA seguía situándolo por encima del 10%. Una cifra absoluta de empleo no equivale a pleno empleo.', visualLabel: 'Más ocupación puede convivir con desempleo elevado', visuals: { key: { value: '>10 %', label: 'Tasa de paro EPA citada', period: '1T 2026' }, trend: { available: false, labels: [], values: [], label: 'Ocupación y tasa de paro', unit: 'Son medidas distintas del mercado laboral' }, comparison: { labels: ['Ocupados','Tasa de paro'], values: [22.293,10.83], label: 'Récord de ocupación y desempleo', unit: 'millones / % · 1T 2026' }, caveat: 'La ocupación absoluta crece también cuando crecen la población y la población activa.' } },
  'juventud-emancipacion': { prompt: 'Casi la mitad de las personas de 26 a 34 años sigue viviendo con sus padres', aliases: ['jóvenes viven con sus padres','la mitad de los jóvenes no se emancipa','emancipación juvenil imposible','los jóvenes no pueden independizarse'], propositions: ['Una proporción muy grande de personas jóvenes convive con sus progenitores.','Vivir con los padres demuestra por sí solo que nadie puede emanciparse.','La media nacional explica igual la situación de todos los jóvenes.'], concern: 'El acceso a una vivienda independiente sigue siendo difícil para mucha juventud, aunque las causas cambian según renta, empleo, territorio y familia.', supports: 'El 44,3% de las personas de 26 a 34 años convivía con sus progenitores en la medición disponible.', limit: 'Vivir con los padres no demuestra por sí solo imposibilidad: también puede responder a preferencias, cuidados o decisiones económicas.', question: '¿Qué edad, territorio, renta y situación laboral quieres comparar?', reply: 'Casi la mitad de las personas de 26 a 34 años sigue viviendo con sus padres. Es una señal clara de acceso difícil a la vivienda, aunque la causa varía según renta, empleo, territorio y familia.', visualLabel: 'Una media de convivencia señala acceso difícil, no una única historia', visuals: { key: { value: '44,3 %', label: 'Personas de 26–34 que conviven con sus progenitores', period: 'Última medición disponible' }, trend: { available: false, labels: [], values: [], label: 'Emancipación por edad, renta y territorio', unit: 'La media nacional oculta diferencias relevantes' }, caveat: 'La convivencia con los progenitores no identifica por sí sola la causa ni la intención de cada hogar.' } },
  'politicos-corruptos': { prompt: 'Todos los políticos son corruptos', aliases: ['todos los políticos roban','la política está llena de corruptos','ningún político es honrado','corrupción de todos los partidos'], propositions: ['España ha sufrido redes importantes de corrupción política.','Todos los políticos son corruptos.','El número de personas investigadas mide toda la corrupción existente.'], concern: 'La corrupción política relevante merece control, pero generalizarla a todas las personas y cargos impide distinguir redes, instituciones y responsabilidades concretas.', supports: 'España ha sufrido redes importantes de corrupción bajo administraciones y partidos diferentes.', limit: 'Los procedimientos afectan a una minoría entre cientos de miles de cargos y empleados públicos, y la corrupción no detectada no puede estimarse con un recuento exacto.', question: '¿Qué caso, resolución judicial o institución concreta quieres comprobar?', reply: 'España tiene corrupción política relevante, pero “todos son corruptos” es falso y borra la diferencia entre instituciones limpias y redes delictivas concretas.', visualLabel: 'Casos reales no convierten una generalización en un recuento', visuals: { key: { value: 'Casos concretos', label: 'La incidencia no se obtiene contando titulares', period: 'Actualidad' }, trend: { available: false, labels: [], values: [], label: 'Corrupción investigada y condenada', unit: 'Casos detectados no miden por sí solos el universo completo' }, caveat: 'Una respuesta responsable debe distinguir denuncia, investigación, acusación, condena y responsabilidad institucional.' } },
  'recaudacion-no-factura-hogar': { prompt: 'Si la recaudación tributaria sube un 10,4%, todos pagan un 10,4% más', aliases: ['todos pagan un 10,4% más','Hacienda sube los impuestos a todos','recaudación y factura de cada hogar','si recauda más todos pagamos más'], propositions: ['Los ingresos tributarios agregados crecieron un 10,4% en 2025.','Cada hogar pagó un 10,4% más.','La recaudación agregada equivale a la presión fiscal de una familia concreta.'], concern: 'La recaudación total puede aumentar aunque el efecto sea distinto por impuesto, renta, deducciones, contribuyente y territorio.', supports: 'Los ingresos tributarios agregados crecieron un 10,4% en 2025 según el informe citado.', limit: 'Los ingresos agregados suman impuestos, contribuyentes y bases distintas; no muestran una subida uniforme para cada hogar.', question: '¿Qué impuesto, renta, situación familiar y periodo quieres comparar?', reply: 'La recaudación total subió un 10,4%, pero eso no significa que cada hogar pagara un 10,4% más. Es un agregado, no una factura individual.', visualLabel: 'Recaudación total y factura familiar son medidas distintas', visuals: { key: { value: '+10,4 %', label: 'Crecimiento de los ingresos tributarios agregados', period: '2025' }, trend: { available: false, labels: [], values: [], label: 'Ingresos, bases y efecto por hogar', unit: 'Un agregado nacional no describe una factura individual' }, comparison: { labels: ['Ingresos','Bases imponibles','Medidas'], values: [10.4,7,2.7], label: 'Componentes del crecimiento tributario', unit: '% · informe anual citado' }, caveat: 'Para saber quién pagó más hay que identificar el impuesto, la renta, las deducciones y el territorio.' } },
  'arope-no-es-pobreza-absoluta': { prompt: 'El AROPE mide pobreza absoluta', aliases: ['AROPE es pobreza absoluta','AROPE significa indigencia','riesgo de pobreza es pobreza extrema','una persona AROPE es pobre absoluta'], propositions: ['AROPE es un indicador oficial de riesgo de pobreza o exclusión social.','AROPE es una única línea de pobreza absoluta.','Todas las personas incluidas tienen la misma intensidad de privación.'], concern: 'El indicador permite medir riesgo de pobreza o exclusión, pero combina dimensiones diferentes y no describe idéntica gravedad en todos los casos.', supports: 'AROPE es un indicador oficial que combina pobreza relativa, carencia material y social severa y baja intensidad laboral.', limit: 'La tasa no equivale a decir que una de cada cuatro personas viva en indigencia o pobreza extrema.', question: '¿Quieres comparar pobreza relativa, carencia material severa o el indicador AROPE completo?', reply: 'AROPE significa riesgo de pobreza o exclusión social, no pobreza absoluta para todas las personas incluidas. Es un indicador compuesto y sus componentes importan.', visualLabel: 'Indicador compuesto, no una única línea de indigencia', visuals: { key: { value: '25,7 %', label: 'Tasa AROPE disponible', period: '2025' }, trend: { available: false, labels: [], values: [], label: 'AROPE y componentes', unit: 'Las dimensiones no son intercambiables' }, caveat: 'La cifra debe desagregarse antes de convertirla en una afirmación sobre pobreza extrema.' } },
  'espana-recesion': { prompt: 'España está en recesión', aliases: ['la economía española está en recesión','España ya está en recesión','el PIB cae en España','crisis económica es recesión'], propositions: ['La economía puede tener problemas de renta, productividad o coste de vida.','España está en recesión según la cifra disponible.','El crecimiento del PIB demuestra que todos los hogares están mejor.'], concern: 'Una familia puede sentirse peor por vivienda, salarios o precios aunque el PIB no esté cayendo; ambas preguntas no son equivalentes.', supports: 'La Contabilidad Nacional registró un crecimiento interanual del PIB real del 2,7% en el primer trimestre de 2026.', limit: 'El crecimiento del PIB no demuestra que todos los hogares estén mejor ni resuelve por sí solo la distribución de la renta.', question: '¿Hablamos de recesión técnica, PIB, renta disponible o coste de vida?', reply: 'La cifra disponible no describe una recesión: el PIB real creció un 2,7% interanual en el primer trimestre de 2026. Eso tampoco significa que todas las familias estén viviendo mejor.', visualLabel: 'Actividad económica y bienestar familiar no son la misma medida', visuals: { key: { value: '+2,7 %', label: 'Crecimiento interanual del PIB real', period: '1T 2026' }, trend: { available: false, labels: [], values: [], label: 'PIB, renta y coste de vida', unit: 'Una cifra agregada no resume la experiencia de cada hogar' }, caveat: 'La recesión describe la actividad económica; no es sinónimo de que no existan problemas de renta, productividad o precios.' } },
  'demasiados-graduados': { prompt: 'España tiene demasiados universitarios', aliases: ['hay demasiados universitarios','sobran graduados','estudiar una carrera no sirve','España está sobrecualificada'], propositions: ['Existe sobrecualificación en campos y empleos concretos.','España tiene demasiadas personas con estudios superiores en términos generales.','El total de graduados determina por sí solo la mezcla óptima de cualificaciones.'], concern: 'El desajuste entre formación, vacantes, salarios y territorio puede ser real sin que estudiar sea el problema.', supports: 'España combina alta titulación superior con déficits de cualificaciones intermedias y sobrecualificación en algunos campos.', limit: 'El total de graduados no dice cuál es la mezcla óptima por especialidad ni sustituye el análisis de vacantes, salarios y movilidad.', question: '¿Qué estudios, ocupación, salario y territorio quieres comparar?', reply: 'El problema no es estudiar demasiado: es el desajuste entre formación, vacantes, salarios y territorio. Hay sobrecualificación en algunos campos y escasez de perfiles técnicos en otros.', visualLabel: 'Nivel de estudios y encaje laboral no son la misma medida', visuals: { key: { value: 'Desajuste', label: 'Formación, vacantes y salarios no encajan igual', period: 'Situación estructural' }, trend: { available: false, labels: [], values: [], label: 'Cualificación y empleo por campo', unit: 'El promedio nacional oculta diferencias por especialidad y territorio' }, caveat: 'No se puede concluir que todas las personas graduadas estén sobrecualificadas ni que la educación superior sea la causa.' } },
  'subida-vivienda-no-todas-igual': { prompt: 'Si la vivienda sube un 12,9%, todas las casas suben lo mismo', aliases: ['todas las casas suben un 12,9%','12,9% en cada vivienda','el precio medio vale para cada casa','la vivienda sube igual en todas partes'], propositions: ['El índice nacional de vivienda libre registró una subida media interanual del 12,9%.','Cada vivienda, barrio y comunidad subió exactamente lo mismo.','El índice nacional de compraventas mide también los alquileres.'], concern: 'La subida media nacional es útil para describir una tendencia, pero no convierte el mismo porcentaje en una regla para cada vivienda.', supports: 'El índice nacional de vivienda libre registró una subida interanual media del 12,9% en el último periodo disponible.', limit: 'Una media de compraventas puede ocultar diferencias por territorio, tipo de vivienda y momento; además, no equivale a un índice nacional de alquileres.', question: '¿Qué ciudad, tipo de vivienda y mercado quieres comparar?', reply: 'El 12,9% es una subida media del índice de vivienda libre, no una regla para cada casa. El dato no mide alquileres ni elimina las diferencias entre barrios y comunidades.', visualLabel: 'Una media nacional no es el precio de cada vivienda', visuals: { key: { value: '+12,9 %', label: 'Subida interanual media del índice', period: '1T 2026' }, trend: { available: false, labels: [], values: [], label: 'Precios por territorio y tipo de vivienda', unit: 'La media nacional no describe cada barrio' }, caveat: 'El índice mide vivienda libre comprada y no equivale automáticamente al mercado de alquiler.' } },
  'inmigracion-flujos-no-total': { prompt: 'Las llegadas irregulares representan toda la inmigración que vive en España', aliases: ['las pateras son toda la inmigración','llegadas irregulares igual a inmigrantes','todos los inmigrantes llegan irregularmente','la inmigración son las llegadas en patera'], propositions: ['Las llegadas irregulares por mar y tierra son visibles y plantean retos de control.','Un flujo anual de llegadas irregulares representa a toda la población inmigrante residente.','La inmigración residente solo llega por vías irregulares.'], concern: 'Las llegadas irregulares son una parte visible del fenómeno, pero no equivalen al conjunto de la inmigración ni a la población nacida fuera que ya reside en España.', supports: 'En 2025 se registraron 36.775 llegadas irregulares frente a más de 10 millones de residentes nacidos en el extranjero.', limit: 'Una cifra de llegadas y una cifra de población residente miden flujos y stocks distintos; no deben compararse sin periodo y definición.', question: '¿Hablamos de llegadas de un año, vías de entrada o población residente?', reply: 'Las llegadas irregulares son una parte visible del fenómeno, no toda la inmigración: en 2025 fueron 36.775 frente a más de 10 millones de residentes nacidos fuera de España. Son medidas distintas.', visualLabel: 'Un flujo anual no representa todo el stock residente', visuals: { key: { value: '36.775', label: 'Llegadas irregulares registradas', period: '2025' }, trend: { available: false, labels: [], values: [], label: 'Flujos y población residente', unit: 'Llegadas y residentes son medidas distintas' }, comparison: { labels: ['Llegadas irregulares','Residentes nacidos fuera'], values: [0.036775,10], label: 'Escalas distintas para no confundir', unit: 'millones · 2025 / último dato disponible' }, caveat: 'No deben sumarse ni interpretarse como si fueran la misma población: una cifra es un flujo anual y la otra un stock residente.' } },
  'recaudacion-tributaria-crece': { prompt: 'La recaudación tributaria bajó en 2025', aliases: ['Hacienda recauda menos','los ingresos tributarios bajaron','la recaudación de impuestos cae','el Estado recaudó menos en 2025'], propositions: ['Los ingresos tributarios agregados crecieron en 2025.','Que aumente la recaudación significa que cada hogar paga más.','Ingresos, bases imponibles y medidas tributarias son el mismo indicador.'], concern: 'La recaudación agregada puede crecer sin describir de forma uniforme lo que paga cada hogar ni la presión fiscal sobre el PIB.', supports: 'El informe anual registra un crecimiento del 10,4% en los ingresos tributarios de 2025.', limit: 'El dato agregado no sustituye una comparación por impuesto, hogar, renta, territorio o presión fiscal; los ingresos, las bases y las medidas son indicadores distintos.', question: '¿Quieres comparar ingresos agregados, un impuesto concreto o la factura de un hogar?', reply: 'La recaudación tributaria no bajó en la cifra agregada citada: los ingresos crecieron un 10,4% en 2025. Eso no dice por sí solo cuánto pagó cada hogar.', visualLabel: 'Recaudación, bases y factura familiar no son lo mismo', visuals: { key: { value: '+10,4 %', label: 'Crecimiento de los ingresos tributarios', period: '2025' }, trend: { available: false, labels: [], values: [], label: 'Ingresos, bases imponibles y medidas', unit: 'Hay que conservar la definición de cada indicador' }, comparison: { labels: ['Ingresos','Bases imponibles','Medidas'], values: [10.4,7,2.7], label: 'Componentes del informe anual', unit: '% · 2025' }, caveat: 'Un crecimiento de la recaudación total no demuestra una subida uniforme para todos los hogares.' } },
};

