export const conversationMvpClaims: ConversationMvpClaim[] = Object.entries(definitions).map(([slug, definition]) => {
  const markdownClaim = markdownClaims.find((claim) => claim.slug === slug);
  return {
    slug,
    topicSlug: markdownClaim?.topicSlugs?.[0] || undefined,
    ...definition,
    provenance: { sourceRefs: markdownClaim?.sourceRefs ?? [], evidenceIds: markdownClaim?.evidenceIds ?? [] },
  };
}).filter((item) => {
  const markdownClaim = markdownClaims.find((claim) => claim.slug === item.slug);
  // Markdown content is the canonical published source. The legacy claim
  // array is still used above for older records, but it must not hide newer
  // published families from the conversation library.
  return markdownClaim?.status === 'published';
});
